dsfd_vm_static_wfc.sv.text:
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------
// dsfd_vm_static_wfc (claude S81 VM owner r9, 2026-10-14): the STATIC VM end of the WFC stage kit's VM channels
// (die master dsfd_wfc_stg = dsfd_wfc_stg_cl: t_swv/t_swd, t_srv/t_srd out, f_swr, f_srr, f_swa, f_srq in).
// Successor of dsfd_vm_wfc_ep (RTT grant receivers lrx_rtt + one in-order op pipe): the static VM takes EVERY kit
// request the serial cycle it arrives (one write and one read pair a serial cycle, never stalled), so the grants are
// constant-high levels from flops and no receiver queue exists (owner rule 2026-10-14T18:59).
// Die ports (serial domain, directions the VM's; S-BIND packing):
//   f_wfc 560 = {f_srd 31 {v1, row1 15, row0 15}, f_srv, f_swd 527 {addr 15, data 512}, f_swv}   (lsb f_swv)
//   t_wfc 1029 = {t_err, t_srq 1026 {rv1, rq1 512, rv, rq 512}, t_srg, t_swg}                    (lsb t_swg)
// Function (stream domain after the fixed 3:4 transfer ot_s81_vm_x34 W 560):
//   write  addr 0 .. 16383 -> VM write source 52 {row addr[13:0], mask ffff, data}; addr 15'h7fff = the kit's START
//          doorbell (POSTED kit: its own t_ks carries START to the capture; the doorbell is not a VM op and is
//          ordered after every earlier write of the channel by construction: one request a serial cycle, in order,
//          each written at a fixed edge); any other addr >= 16384 -> t_err (sticky), nothing written.
//   read   row0 (and row1 when v1) -> aux read ports 8 + row[1:0] (FSR lane rule; a pair on one lane = fault);
//          the returned rows leave on t_srq at ONE fixed latency (the core's L 12 + this block's two registers +
//          the transfers): request at serial edge k of epoch n -> t_srq registered at serial edge k of epoch n + 5.
//          Reads and writes of one serial cycle: the read sees the VM before that write (separate fixed paths; the
//          kit never reads a row it writes in the same cycle: its prefetch runs after k_done).
//   t_swg / t_srg  = serial live (constant high after reset: every request is accepted, never a back-pressure level)
//   t_err          = sticky: write/read range error, read lane collision, return-slot mismatch, x34/x43 assertion,
//                    or the VM's own fault level (POSTED kit: checked at the transaction end, as the legacy t_err).
// Phase bookkeeping: x34 presents requests at stream sample indices 2 / 3 / 0; the fixed 15-edge stream path
// (decode 1 + core 13 + return 1) lands every response on sample index 2 / 3 / 0 of ot_s81_vm_x43 (never 1).
// Mutant OT_VM_WFC_MUT_PAIR: row1's response is returned in the rq slot (pair swapped): must FAIL.
// ---------------------------------------------------------------------------------------------------------------
module dsfd_vm_static_wfc #(parameter integer RLAT = 13) (
    input  wire          ck, rst,               // serial
    input  wire          cks, rss,              // stream
    input  wire [559:0]  f_wfc,
    output wire [1028:0] t_wfc,
    // stream side to / from dsfd_vm_static_core
    output reg           w_v, output reg [13:0] w_row, output reg [511:0] w_d,
    output reg  [3:0]    a_v, output reg [55:0] a_row,          // aux ports 8..11
    input  wire [3:0]    e_v, input wire [2047:0] e_d,          // aux ports 8..11 returns (core output registers)
    input  wire          vm_fault,                              // stream level
    output wire          fault                                  // stream level (this endpoint's own faults)
);
    // ---------------------------------------------------------------- serial -> stream
    wire xv; wire [559:0] xd; wire x34f;
    ot_s81_vm_x34 #(.W(560)) u_xi (.s_ck(ck), .s_rst_n(rst), .s_v(f_wfc[0] | f_wfc[528]), .s_d(f_wfc),
        .t_ck(cks), .t_rst_n(rss), .o_v(xv), .o_d(xd), .fault(x34f));
    reg [1:0] tq;
    always @(posedge cks or negedge rss) if (!rss) tq <= 2'b00; else tq <= {tq[0], 1'b1};
    wire tn = tq[1];
    wire        q_wv  = xv && xd[0];
    wire [14:0] q_wa  = xd[527:513];
    wire [511:0] q_wd = xd[512:1];
    wire        q_rv  = xv && xd[528];
    wire [14:0] q_r0  = xd[529 +: 15];
    wire [14:0] q_r1  = xd[544 +: 15];
    wire        q_v1  = xd[559];
    reg err;
    // ---------------------------------------------------------------- decode register (edge X + 1)
    reg [RLAT:0] dv0, dv1; reg [1:0] dl0 [0:RLAT]; reg [1:0] dl1 [0:RLAT];
    always @(posedge cks) begin : p_dec integer k; reg r0ok, r1ok;
        if (!tn) begin w_v <= 1'b0; a_v <= 4'd0; err <= 1'b0; dv0 <= '0; dv1 <= '0; end
        else begin
            w_v <= q_wv && q_wa < 15'd16384;
            if (q_wv && q_wa >= 15'd16384 && q_wa != 15'h7fff) err <= 1'b1;
            r0ok = q_rv && q_r0 < 15'd16384;
            r1ok = q_rv && q_v1 && q_r1 < 15'd16384;
            if ((q_rv && q_r0 >= 15'd16384) || (q_rv && q_v1 && q_r1 >= 15'd16384)) err <= 1'b1;
            if (r0ok && r1ok && q_r0[1:0] == q_r1[1:0]) err <= 1'b1;            // pair on one FSR lane
            a_v <= (r0ok ? (4'd1 << q_r0[1:0]) : 4'd0) | ((r1ok && !(r0ok && q_r0[1:0] == q_r1[1:0])) ? (4'd1 << q_r1[1:0]) : 4'd0);
            dv0 <= {dv0[RLAT-1:0], r0ok}; dv1 <= {dv1[RLAT-1:0], r1ok && !(r0ok && q_r0[1:0] == q_r1[1:0])};
        end
        w_row <= q_wa[13:0]; w_d <= q_wd;
        for (k = 0; k < 4; k = k + 1) a_row[14*k +: 14] <= (q_rv && q_r1[1:0] == k[1:0] && !(q_r0[1:0] == k[1:0])) ? q_r1[13:0] : q_r0[13:0];
        dl0[0] <= q_r0[1:0]; dl1[0] <= q_r1[1:0];
        for (k = 1; k <= RLAT; k = k + 1) begin dl0[k] <= dl0[k-1]; dl1[k] <= dl1[k-1]; end
    end
    // ---------------------------------------------------------------- return register (edge X + 15)
    // dv*[RLAT] / dl*[RLAT] = the decode of the request whose core return is registered at this edge's inputs
    reg [1025:0] r_q; reg r_bad;
    wire        e0 = dv0[RLAT], e1 = dv1[RLAT];
    wire [1:0]  l0 = dl0[RLAT], l1 = dl1[RLAT];
    always @(posedge cks) begin
        if (!tn) begin r_q <= 1026'd0; r_bad <= 1'b0; end
        else begin
`ifdef OT_VM_WFC_MUT_PAIR
            r_q <= {e0, e0 ? e_d[512*l0 +: 512] : 512'd0, e1, e1 ? e_d[512*l1 +: 512] : 512'd0};
`else
            r_q <= {e1, e1 ? e_d[512*l1 +: 512] : 512'd0, e0, e0 ? e_d[512*l0 +: 512] : 512'd0};
`endif
            // every return slot must carry exactly the expected aux ports (a missing / stray row = fault)
            if (e_v != ((e0 ? (4'd1 << l0) : 4'd0) | (e1 ? (4'd1 << l1) : 4'd0))) r_bad <= 1'b1;
        end
    end
    // ---------------------------------------------------------------- stream -> serial
    wire ov; wire [1025:0] od; wire x43f;
    ot_s81_vm_x43 #(.W(1026)) u_xo (.t_ck(cks), .t_rst_n(rss), .s_v(r_q[512] | r_q[1025]), .s_d(r_q),
        .s_ck(ck), .s_rst_n(rst), .o_v(ov), .o_d(od), .fault(x43f));
    // serial outputs: grants = serial live, t_err = sticky (registered in the serial domain from stream levels)
    reg [1:0] sq; always @(posedge ck or negedge rst) if (!rst) sq <= 2'b00; else sq <= {sq[0], 1'b1};
    reg g_q, e_q;
    wire own = err | r_bad | x34f;
    always @(posedge ck) begin g_q <= sq[1]; e_q <= sq[1] && (own | x43f | vm_fault); end
    assign t_wfc = {e_q, od, g_q, g_q};
    assign fault = own | x43f;
endmodule
`default_nettype wire

dsfd_vm_static_landing.sv.text:
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------
// dsfd_vm_static_landing (claude S81 VM owner r8, 2026-10-14): STATIC LARM.  Row producers that send bare 512-b rows
// (HBM scan service aSW: two rows a beat; selector; collector) land at compiler-armed addresses with NO FIFO, drain
// arbiter, grant, room/credit or timeout (the legacy dsfd_vm_ll landing lanes + drain arbiter + t_cts room are void
// under the owner rule 2026-10-14T18:59).
//   LARM (engine 12 native code 6, arg[20:17] = group, arg[13:0] = base row): group 0 = scan service (lanes 0/1,
//   OFF 0/1, STRIDE 2), group 5 = selector (lane 2, STRIDE 1), group 6 = collector (lane 3, STRIDE 1).  The arm takes
//   effect for rows arriving at the landing pins on edges >= arm edge + 1 and resets the lane's row count.
//   Row k (k = 0, 1, ... since the arm) of lane L is written to base + OFF_L + STRIDE_L * k, full 16-word mask, on
//   write source L at the edge after its arrival (one register stage; the write service adds its own fixed stages).
//   Every row is therefore committed at a fixed, compiler-known cycle; the compiler places the rows so that the static
//   bank rule holds (a violation is a write-service fault, never a delay).
// Faults (sticky): [0] row on an unarmed lane, [1] address beyond 16383, [2] LARM of an unknown group.
// ---------------------------------------------------------------------------------------------------------------
module dsfd_vm_static_landing (
    input  wire          ck, rst_n,
    input  wire          larm_v, input wire [3:0] larm_g, input wire [13:0] larm_base,
    input  wire [3:0]    i_v,                  // lanes: 0/1 scan service rows a0/a1, 2 selector, 3 collector
    input  wire [2047:0] i_d,
    output reg  [3:0]    o_v,
    output reg  [55:0]   o_row,
    output reg  [2047:0] o_d,
    output reg  [2:0]    fault
);
    reg [1:0] rr;
    always @(posedge ck or negedge rst_n) if (!rst_n) rr <= 2'b00; else rr <= {rr[0], 1'b1};
    wire rn = rr[1];
    reg [3:0] armed; reg [14:0] nxt [0:3];
    wire [3:0] arm_l = {larm_v && larm_g == 4'd6, larm_v && larm_g == 4'd5, larm_v && larm_g == 4'd0, larm_v && larm_g == 4'd0};
    always @(posedge ck) begin : p_l integer l; reg [14:0] st;
        if (!rn) begin armed <= 4'd0; o_v <= 4'd0; fault <= 3'd0; end
        else begin
            if (larm_v && larm_g != 4'd0 && larm_g != 4'd5 && larm_g != 4'd6) fault[2] <= 1'b1;
            for (l = 0; l < 4; l = l + 1) begin
                st = (l < 2) ? 15'd2 : 15'd1;
                o_v[l] <= i_v[l] && armed[l] && nxt[l] < 15'd16384;
                if (i_v[l] && !armed[l]) fault[0] <= 1'b1;
                if (i_v[l] && armed[l] && nxt[l] >= 15'd16384) fault[1] <= 1'b1;
                o_row[14*l +: 14] <= nxt[l][13:0];
`ifdef OT_VM_LANDING_MUT_STRIDE
                if (i_v[l] && armed[l]) nxt[l] <= nxt[l] + 15'd1;                  // MUTANT: scan rows interleave wrong
`else
                if (i_v[l] && armed[l]) nxt[l] <= nxt[l] + st;
`endif
                if (arm_l[l]) begin armed[l] <= 1'b1; nxt[l] <= {1'b0, larm_base} + ((l == 1) ? 15'd1 : 15'd0); end
            end
        end
    end
    always @(posedge ck) o_d <= i_d;
endmodule
`default_nettype wire

dsfd_vm_static_bank128.sv.text:
`timescale 1ns/1ps
// Native scheduled one-bank leaf: uses BOTH real1R1W macro ports. No queues,
// ready, credits, arbiters or retries. Addresses are physical bank-local[13:5].
// Compiler owns requests and read-before-write same-address semantics.
// Pin sample at edgeE: write commits at E+1, read appears registered at E+2.
// Commit output is observation of the very SRAM w_ce edge, never admission.
module dsfd_vm_static_bank128(
 input wire ck,rst_n,
 input wire i_rv,input wire [8:0] i_ra,input wire [7:0] i_rt,
 input wire i_wv,input wire [8:0] i_wa,input wire [127:0] i_wd,
 input wire [3:0] i_wm,input wire [7:0] i_wt,
 output reg o_rv,output reg [127:0] o_rd,output reg [7:0] o_rt,
 output reg o_commit,output reg [8:0] o_ca,
 output reg [3:0] o_cm,output reg [7:0] o_ct
);
 reg [1:0] reset_release;
 always @(posedge ck or negedge rst_n)
  if(!rst_n)reset_release<=0;else reset_release<={reset_release[0],1'b1};
 wire rn=reset_release[1];

 reg rvq,wvq,rdue;reg [8:0] raq,waq;reg [127:0] wdq;
 reg [3:0] wmq;reg [7:0] rtq,rt1,wtq;
 always @(posedge ck or negedge rn)begin
  if(!rn)begin rvq<=0;wvq<=0;rdue<=0;o_rv<=0;o_commit<=0;end
  else begin rvq<=i_rv;wvq<=i_wv;rdue<=rvq;o_rv<=rdue;
`ifdef OT_VM_BANK_MUT_EARLY_COMMIT
   o_commit<=i_wv;
`else
   o_commit<=wvq;
`endif
  end
 end
 always @(posedge ck)begin
  raq<=i_ra;waq<=i_wa;wdq<=i_wd;wmq<=i_wm;rtq<=i_rt;wtq<=i_wt;rt1<=rtq;
  o_rt<=rt1;o_ca<=waq;o_cm<=wmq;o_ct<=wtq;
 end
 wire [127:0] mr;
 `ifdef OT_VM_BANK_MUT_MASK
 wire [127:0] mask={128{1'b1}};
`else
 wire [127:0] mask={{32{wmq[3]}},{32{wmq[2]}},{32{wmq[1]}},{32{wmq[0]}}};
`endif
 ot_sram_1r1w_512x128_m4_r2c2 u_sram(.clk(ck),.r_ce_in(rvq),.r_addr_in(raq),.rd_out(mr),
 .w_ce_in(wvq),.w_addr_in(waq),.wd_in(wdq),.w_mask_in(mask),
 .rr_en(2'd0),.rr_addr(14'd0),.cr_en(2'd0),.cr_sel(14'd0));
 always @(posedge ck)o_rd<=mr;
endmodule

dsfd_vm_static_return.sv.text:
`timescale 1ns/1ps
// Statically scheduled row-group assembly, one128b slice. No waiting/retry.
// Return tag={group(8-SLOT_BITS),slot(SLOT_BITS)}; default16 or wide32 rows. Two group buffers (group parity) permit adjacent
// groups on different physical bank/hop phases. The compiler supplies the exact
// release edge/mask. Missing, duplicate or overwritten rows are schedule faults.
// A row must arrive at least one edge before release, as registered timing needs.
module dsfd_vm_static_return #(parameter integer DW=128,parameter integer NROW=16,parameter integer SLOT_BITS=$clog2(NROW))(
 input wire ck,rst_n,
 input wire [31:0] i_v,
 input wire [255:0] i_tag,
 input wire [32*DW-1:0] i_data,
 input wire release_v,input wire [7-SLOT_BITS:0] release_group,input wire [NROW-1:0] release_mask,
 output reg [NROW-1:0] o_v,output reg [NROW*DW-1:0] o_data,
 output reg [7-SLOT_BITS:0] o_group,output reg fault
);
 reg [1:0] reset_release;
 always @(posedge ck or negedge rst_n)
  if(!rst_n)reset_release<=0;else reset_release<={reset_release[0],1'b1};
 wire rn=reset_release[1];

 reg [2*NROW-1:0] valid;
 reg [7-SLOT_BITS:0] groups[0:2*NROW-1];reg [DW-1:0] data[0:2*NROW-1];
 reg [2*NROW-1:0] valid_n,used;
 reg bad,complete;integer j,idx,s;reg [7:0] tag;
 always @*begin
  valid_n=valid;used=0;bad=0;complete=1;
  if(release_v)begin
   for(s=0;s<NROW;s=s+1)if(release_mask[s])begin
    idx=NROW*release_group[0]+s;
    if(!valid[idx] || groups[idx]!=release_group)complete=0;
    valid_n[idx]=0;
   end
   if(!complete)bad=1;
  end
  for(j=0;j<32;j=j+1)if(i_v[j])begin
   tag=i_tag[8*j+:8];idx=NROW*tag[SLOT_BITS]+tag[SLOT_BITS-1:0];
   if(tag[1:0]!=(j%4))bad=1;
   if(valid_n[idx] || used[idx])bad=1;
   used[idx]=1;valid_n[idx]=1;
  end
 end
 always @(posedge ck or negedge rn)begin
  if(!rn)begin valid<=0;o_v<=0;fault<=0;o_group<=0;end
  else begin
   valid<=valid_n;fault<=fault|bad;
`ifdef OT_VM_RETURN_MUT_MASK
   o_v<=release_v ? release_mask : {NROW{1'b0}}; // mutant silently releases missing rows
`else
   o_v<=release_v && complete ? release_mask : {NROW{1'b0}};
`endif
   o_group<=release_group;
  end
 end
 always @(posedge ck)begin : outputs integer q;
  if(release_v)for(q=0;q<NROW;q=q+1)o_data[DW*q+:DW]<=data[NROW*release_group[0]+q];
 end
 genvar g;
 initial begin
  if(NROW!=16 && NROW!=32)$error("native return supports16or32rows");
 end
 generate for(g=0;g<2*NROW;g=g+1)begin:slot_store
  reg hit;reg [DW-1:0] next_data;reg [7-SLOT_BITS:0] next_group;integer k,p;
  always @*begin
   hit=0;next_data=0;next_group=0;
   for(k=0;k<8;k=k+1)begin
    p=4*k+(g%4);
    if(i_v[p] && i_tag[8*p+:SLOT_BITS+1]==g)begin
     hit=1;next_data=next_data|i_data[DW*p+:DW];next_group=next_group|i_tag[8*p+SLOT_BITS+:8-SLOT_BITS];
    end
   end
  end
  always @(posedge ck)if(hit)begin data[g]<=next_data;groups[g]<=next_group;end
 end endgenerate
endmodule

dsfd_vm_static_capl.sv.text:
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------
// dsfd_vm_static_capl (claude S81 VM owner r9, 2026-10-14): ONE STATIC capture lane of the S81 layer-die VM (serial
// 0.9 GHz).  Successor of the dynamic dsfd_vm_cl (associative row entries, LRU eviction, partial-row timeout: VOID
// under the owner rule 2026-10-14T18:59).  A lane = 8 field roots (8G .. 8G+7) = 16 element inputs a cycle from the
// capture slab (dsfd_sp_capture t_vm: per root {row1 {data32, addr19}, v1, row0 {data32, addr19}, v0}).
// ALIGNMENT CONTRACT (compiler, unchanged from the legacy lane): element k of the lane (root i = 8G + k/2) carries
// addr[7:1] == i, so every element of lane G lands in VM row R = addr[17:4] with R[3:0] = G, word addr[3:0]; the row
// KEY is addr[17:8].  addr[18] set (>= 2^18 words) or a wrong addr[7:1] is a fault (element dropped, fail closed).
// STATIC ASSEMBLY: E direct-mapped row entries, entry = key mod E (no tags searched, no allocation, no victim).
//   * an element merges into entry key mod E (entry empty: it takes the key);
//   * the cycle an entry's 16 words are present it is written (one masked VM row write {row, mask ffff, data}) and
//     cleared: the write cycle is a fixed function of the producers' compiled timeline (the last element's arrival);
//   * PHASE FLUSH: at the capture's phase-drained event (status st[2] rising after st[0], the capture slab's own
//     quota completion) every entry e with a partial row is written at drained + 1 + e (fixed slot, partial mask);
//     the field's last rows of a phase that does not fill a row are the only partial rows.
// FAULTS (sticky, never a delay): [0] range, [1] alignment, [2] alias (an element whose entry holds another key:
//   two live rows of one lane E keys apart = root skew beyond the compiled bound), [3] duplicate word, [4] two rows due
//   on one cycle (full rows of two entries, or a full row inside the flush window).
// Pipeline: S1 (this module's input register = the parent's pin register output) decode + merge into the entry state
// (registered); a completed row leaves from flops one cycle later (o_v / o_row / o_m / o_d).  Latency: element at the
// lane input edge P (its row's last) -> o_* registered at P + 2.
// Mutant OT_VM_CAPL_MUT_WORD: element row1 of every root writes the row0 word slot (words 2j+1 lost): must FAIL.
// ---------------------------------------------------------------------------------------------------------------
module dsfd_vm_static_capl #(parameter integer E = 8) (
    input  wire          ck, rn,              // serial clock, synchronised lane reset (control state only)
    input  wire [3:0]    gid,                 // lane index G (static strap)
    input  wire [831:0]  f_c,                 // 8 roots x {row1 {data32, addr19}, v1, row0 {data32, addr19}, v0} (registered)
    input  wire          flush,               // phase-drained event (one cycle)
    output reg           o_v,
    output reg  [13:0]   o_row,
    output reg  [15:0]   o_m,
    output reg  [511:0]  o_d,
    output reg  [4:0]    flt
);
    localparam integer EB = $clog2(E);
    // ------------------------------------------------------------------ decode
    reg [15:0] ev, eok; reg [9:0] ek [0:15]; reg [3:0] ew [0:15]; reg [31:0] ed [0:15];
    reg f_rng, f_al;
    always @* begin : p_dec integer k; reg [50:0] el; reg v;
        f_rng = 1'b0; f_al = 1'b0;
        for (k = 0; k < 16; k = k + 1) begin
            // root j = k/2: [104 j +: 104] = {row1 51, v1, row0 51, v0}; element k even = row0, odd = row1
            v  = (k % 2 == 0) ? f_c[104*(k/2)] : f_c[104*(k/2) + 52];
            el = (k % 2 == 0) ? f_c[104*(k/2) + 1 +: 51] : f_c[104*(k/2) + 53 +: 51];
            ev[k] = v;
            ek[k] = el[17:8]; ed[k] = el[50:19];
`ifdef OT_VM_CAPL_MUT_WORD
            ew[k] = {el[3:1], 1'b0};
`else
            ew[k] = el[3:0];
`endif
            eok[k] = 1'b0;
            if (v) begin
                if (el[18]) f_rng = 1'b1;
                else if (el[7:1] != {gid, 3'(k / 2)}) f_al = 1'b1;
                else eok[k] = 1'b1;
            end
        end
    end
    // ------------------------------------------------------------------ entry state
    reg [E-1:0] V; reg [9:0] KEY [0:E-1]; reg [15:0] MSK [0:E-1]; reg [511:0] DAT [0:E-1];
    reg [EB:0] fl_c; reg fl_on;              // flush slot counter (entry fl_c - 1 is written this cycle)
    // next-state (combinational) per entry
    reg [E-1:0] nV, full; reg [9:0] nK [0:E-1]; reg [15:0] nM [0:E-1]; reg [511:0] nD [0:E-1];
    reg f_alias, f_dup;
    always @* begin : p_merge integer e, k, w; reg hit; reg [9:0] kk;
        f_alias = 1'b0; f_dup = 1'b0;
        for (e = 0; e < E; e = e + 1) begin
            nV[e] = V[e]; nK[e] = KEY[e]; nM[e] = MSK[e]; nD[e] = DAT[e];
            hit = 1'b0; kk = KEY[e];
            for (k = 0; k < 16; k = k + 1) if (eok[k] && ek[k][EB-1:0] == e[EB-1:0]) begin
                if (!nV[e] && !hit) begin kk = ek[k]; end
                if ((nV[e] || hit) && kk != ek[k]) f_alias = 1'b1;
                else begin
                    for (w = 0; w < 16; w = w + 1) if (ew[k] == w[3:0]) begin
                        if (nM[e][w]) f_dup = 1'b1;
                        nM[e][w] = 1'b1; nD[e][32*w +: 32] = ed[k];
                    end
                    hit = 1'b1;
                end
            end
            if (hit) begin nV[e] = 1'b1; nK[e] = kk; end
            full[e] = nV[e] && nM[e] == 16'hffff;
        end
    end
    // ------------------------------------------------------------------ write selection (registered output)
    always @(posedge ck) begin : p_out integer e; reg [EB:0] nf; reg sel; reg two; integer fe;
        if (!rn) begin
            V <= {E{1'b0}}; o_v <= 1'b0; flt <= 5'd0; fl_on <= 1'b0; fl_c <= '0;
            for (e = 0; e < E; e = e + 1) MSK[e] <= 16'd0;
        end else begin
            sel = 1'b0; two = 1'b0; fe = -1;
            for (e = 0; e < E; e = e + 1) if (full[e]) begin if (sel) two = 1'b1; else begin sel = 1'b1; fe = e; end end
            // flush slot: entry fl_c - 1 at drained + fl_c
            if (fl_on && !sel && nV[fl_c - 1] && nM[fl_c - 1] != 16'd0) begin sel = 1'b1; fe = fl_c - 1; end
            else if (fl_on && sel && nV[fl_c - 1] && nM[fl_c - 1] != 16'd0 && fe != fl_c - 1) two = 1'b1;
            for (e = 0; e < E; e = e + 1) begin
                V[e] <= nV[e] && !(sel && fe == e);
                KEY[e] <= nK[e]; MSK[e] <= (sel && fe == e) ? 16'd0 : nM[e]; DAT[e] <= nD[e];
            end
            o_v <= sel;
            if (sel) begin o_row <= {nK[fe], gid}; o_m <= nM[fe]; o_d <= nD[fe]; end
            if (flush) begin fl_on <= 1'b1; fl_c <= 1; end
            else if (fl_on) begin if (fl_c == E) fl_on <= 1'b0; else fl_c <= fl_c + 1'b1; end
            flt <= flt | {two, f_dup, f_alias, f_al, f_rng};
        end
    end
endmodule
`default_nettype wire

dsfd_vm_static_relay128.sv.text:
`timescale 1ns/1ps
// Fixed scheduled duplex physical hop for NBANK complete bank routes.
// Independent actual clock pins permit native phi-R request/response delivery.
// No availability state, arbitration, handshake, queues or schedule extension.
// Commit metadata is transported unchanged after the real macro edge; relay
// output timing is observation timing, not the underlying write visibility.
module dsfd_vm_static_relay128 #(parameter integer NBANK=8)(
 input wire ck_req,ck_rsp,rst_n,
 input wire [NBANK-1:0] i_rv,i_wv,input wire [9*NBANK-1:0] i_ra,i_wa,
 input wire [8*NBANK-1:0] i_rt,i_wt,input wire [4*NBANK-1:0] i_wm,
 input wire [128*NBANK-1:0] i_wd,
 output reg [NBANK-1:0] o_rv,o_wv,output reg [9*NBANK-1:0] o_ra,o_wa,
 output reg [8*NBANK-1:0] o_rt,o_wt,output reg [4*NBANK-1:0] o_wm,
 output reg [128*NBANK-1:0] o_wd,
 input wire [NBANK-1:0] i_sv,i_cv,input wire [128*NBANK-1:0] i_sd,
 input wire [8*NBANK-1:0] i_st,i_ct,input wire [9*NBANK-1:0] i_ca,
 input wire [4*NBANK-1:0] i_cm,
 output reg [NBANK-1:0] o_sv,o_cv,output reg [128*NBANK-1:0] o_sd,
 output reg [8*NBANK-1:0] o_st,o_ct,output reg [9*NBANK-1:0] o_ca,
 output reg [4*NBANK-1:0] o_cm
);
 reg [1:0] rr,sr;
 always @(posedge ck_req or negedge rst_n)if(!rst_n)rr<=0;else rr<={rr[0],1'b1};
 always @(posedge ck_rsp or negedge rst_n)if(!rst_n)sr<=0;else sr<={sr[0],1'b1};
 always @(posedge ck_req or negedge rr[1])
  if(!rr[1])begin o_rv<=0;o_wv<=0;end else begin o_rv<=i_rv;o_wv<=i_wv;end
 always @(posedge ck_req)begin o_ra<=i_ra;o_rt<=i_rt;o_wa<=i_wa;o_wt<=i_wt;o_wm<=i_wm;o_wd<=i_wd;end
 always @(posedge ck_rsp or negedge sr[1])
  if(!sr[1])begin o_sv<=0;o_cv<=0;end else begin o_sv<=i_sv;o_cv<=i_cv;end
 always @(posedge ck_rsp)begin o_sd<=i_sd;o_st<=i_st;o_ca<=i_ca;o_cm<=i_cm;o_ct<=i_ct;end
endmodule

dsfd_vm_static_scatter_b8_out.sv.text:
`timescale 1ns/1ps
// Second existing scatter stage. Production wsched already reserves bank k and
// packet slot8*(k%4)+k/4. Parent wires each record to its bank-local capture leaf.
// No crossbar or arbitration: rowhash mismatch is a sticky compiler-defect fault.
module dsfd_vm_static_scatter_b8_out #(parameter integer BANK_BASE=0)(
 input wire ck,rst_n,input wire [7:0] i_v,i_we,
 input wire [111:0] i_row,input wire [31:0] i_mask,
 input wire [1023:0] i_data,input wire [63:0] i_tag,
 output reg [7:0] o_v,o_we,output reg [71:0] o_addr,
 output reg [31:0] o_mask,output reg [1023:0] o_data,
 output reg [63:0] o_tag,output reg fault
);
 reg [1:0] reset_release;
 always @(posedge ck or negedge rst_n)
  if(!rst_n)reset_release<=0;else reset_release<={reset_release[0],1'b1};
 wire rn=reset_release[1];wire [7:0] good,bad;
 genvar k;generate for(k=0;k<8;k=k+1)begin:bank
  assign good[k]=(i_row[14*k+:5]^{i_row[14*k+5+:3],2'b00})==BANK_BASE+k;
  assign bad[k]=i_v[k]&&!good[k];
  always @(posedge ck or negedge rn)if(!rn)o_v[k]<=0;else o_v[k]<=i_v[k]&&good[k];
  always @(posedge ck)begin
   o_we[k]<=i_v[k]&&good[k]?i_we[k]:1'b0;
`ifdef OT_VM_DIRECT_SCATTER_MUT_ADDR
   o_addr[9*k+:9]<=i_v[k]&&good[k]?(i_row[14*k+5+:9]^9'h1):9'd0;
`else
   o_addr[9*k+:9]<=i_v[k]&&good[k]?i_row[14*k+5+:9]:9'd0;
`endif
   o_mask[4*k+:4]<=i_v[k]&&good[k]?i_mask[4*k+:4]:4'd0;
`ifdef OT_VM_DIRECT_SCATTER_MUT_DATA
   o_data[128*k+:128]<=i_v[k]&&good[k]?i_data[128*((k+1)%8)+:128]:128'd0;
`else
   o_data[128*k+:128]<=i_v[k]&&good[k]?i_data[128*k+:128]:128'd0;
`endif
   o_tag[8*k+:8]<=i_v[k]&&good[k]?i_tag[8*k+:8]:8'd0;
  end
 end endgenerate
 always @(posedge ck or negedge rn)if(!rn)fault<=0;else fault<=fault|(|bad);
 initial if(BANK_BASE<0 || BANK_BASE>24 || BANK_BASE%8)$error("bank-local scatter base must be0,8,16,24");
endmodule

dsfd_vm_static_core.sv.text:
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------
// dsfd_vm_static_core (claude S81 VM owner r8, 2026-10-14): the STATIC S81 layer-die VM, stream domain (1.2 GHz).
// Composition of real RTL only (no stubs, no behavioural memory): the full-capacity native memory
// dsfd_vm_static512_suhc (4 slices x 32 real ot_sram_1r1w_512x128 banks = 16384 x 512 b, two duplex relay levels,
// return store, native SU/HC return map), the fixed-rule read schedule dsfd_vm_static_rsched, the fixed-rule write
// service dsfd_vm_static_wsched (53 sources -> wdispatch -> compiler-indexed storage -> fixed drain), the sequencer
// engine 12 dsfd_vm_seq_static and the static landing dsfd_vm_static_landing (static LARM).
// Owner rule 2026-10-14T18:59: nothing here waits, stalls, queues by demand, arbitrates or returns a credit.  Every
// client sees a FIXED latency (stream edges, die pin sample -> die output register sample):
//   SU / HC row read  f_*_rqv/rq  -> t_*_rsv/rs        L = 12  (P pin, P+1 FSR, P+11 release, P+12 output register)
//   PQ x read         f_pqx       -> t_pqx (4 rows)    L = 12  (aux ports 0..3 = rows x_addr[17:6]*4 + 0..3)
//   edge aux reads    x_av / x_ar -> x_rv / x_rd       L = 12  (aux 4..7 xio row streams, 8..11 WFC; port = row[1:0])
//   row write         f_*_wq*     -> SRAM commit       lane c: scatter sample P+4+c (+ relay and macro stages of the
//                                                      static512 timeline); the engine CHECK observes the commits
//   engine 12         c_cmd       -> c_done            6 (dsfd_vm_seq_static DLAT)
//   Engram MIX4 read  f_mx_rq*    -> t_mx_rs* (20)     L = 12  (lane i: slot {G(i), row[1:0]} on logical port = slot)
// Write sources: 0..15 SU slots, 16..23 HC slots, 24..27 landing lanes (scan a0/a1, selector, collector), 28..31 MIX4,
// 32..43 + 48..51 the static capture lanes 0..15 (dsfd_vm_static_cap), 44..47 the collective landing words
// (dsfd_vm_static_xio, LARM group 7), 52 the WFC kit writes (dsfd_vm_static_wfc).  All fixed rules, no queue.
// Native engine codes (forwarded to the edge services on nf_v / nf_d): 4 STREAM (dsfd_vm_static_xio),
// 6 LARM (groups 0 / 5 / 6 here); legacy collective ops 5/7/group7 fault. Done = the seq's fixed DLAT.
// Every service fault is ORed onto the engine's legacy-fault input (seq flt[10] -> c_st[0]).
// ---------------------------------------------------------------------------------------------------------------
module dsfd_vm_static_core (
    input  wire          cks, rss,
    // sequencer engine 12
    input  wire [84:0]   c_cmd, output wire [8:0] c_done, output wire [1:0] c_st,
    output wire          t_inp_su, t_inp_hc,
    // SU v2 row slots (16 rd + 16 wr)
    input  wire [15:0]   f_su_rqv, input wire [223:0] f_su_rq,
    output reg  [15:0]   t_su_rsv, output reg [8191:0] t_su_rs,
    input  wire [15:0]   f_su_wqv, input wire [223:0] f_su_wq, input wire [255:0] f_su_wqm, input wire [8191:0] f_su_wqd,
    // HC v2 row slots (2 rd + 8 wr)
    input  wire [1:0]    f_hc_rqv, input wire [27:0] f_hc_rq,
    output reg  [1:0]    t_hc_rsv, output reg [1023:0] t_hc_rs,
    input  wire [7:0]    f_hc_wqv, input wire [111:0] f_hc_wq, input wire [127:0] f_hc_wqm, input wire [4095:0] f_hc_wqd,
    // PQ native x read {x_addr 19, x_re} -> {x_q 2048, x_rv}
    input  wire [19:0]   f_pqx, output reg [2048:0] t_pqx,
    // edge services (dsfd_vm_static_xio / dsfd_vm_static_wfc): aux read ports 4..11 (aux p carries rows with
    // row[1:0] == p mod 4, the FSR lane rule), returns registered at the request pin + 12 like every client
    input  wire [7:0]    x_av, input wire [111:0] x_ar,
    output reg  [7:0]    x_rv, output reg [4095:0] x_rd,
    // engine 12 native forward (codes 4..7) to the edge services
    output wire          nf_v, output wire [83:0] nf_d,
    // Engram MIX4 endpoint (dsfd_engram_mix4_c rq/rs/wq): 20 reads an edge (fixed return slots), 4 row writes (sources 28..31)
    input  wire [19:0]   f_mx_rqv, input wire [279:0] f_mx_rq,
    output reg  [19:0]   t_mx_rsv, output reg [10239:0] t_mx_rs,
    input  wire [3:0]    f_mx_wqv, input wire [55:0] f_mx_wq, input wire [63:0] f_mx_wqm, input wire [2047:0] f_mx_wqd,
    // landing rows (stream domain, after the fixed 3:4 transfer): lanes 0/1 scan a0/a1, 2 selector, 3 collector
    input  wire [3:0]    l_v, input wire [2047:0] l_d,
    // edge write sources: capture 16 (sources 32..43, 48..51), collective landing 4 (44..47), WFC 1 (52)
    input  wire [15:0]   cp_v, input wire [223:0] cp_row, input wire [255:0] cp_m, input wire [8191:0] cp_d,
    input  wire [3:0]    cl_v, input wire [55:0] cl_row, input wire [63:0] cl_m, input wire [2047:0] cl_d, input wire [31:0] cl_t,
    input  wire          wf_v, input wire [13:0] wf_row, input wire [511:0] wf_d,
    // external service faults ORed in (e.g. the 3:4 transfers)
    input  wire          x_flt,
    output wire          vm_fault
);
    wire ck = cks;
    reg [1:0] rr;
    always @(posedge ck or negedge rss) if (!rss) rr <= 2'b00; else rr <= {rr[0], 1'b1};
    wire rn = rr[1];

    // ---------------------------------------------------------------- read schedule
    // aux 0..3: PQ x rows (4 an edge); aux 4..7: outbound row streams (xio); aux 8..11: WFC kit reads
    wire [11:0] aux_v = {x_av, {4{f_pqx[0]}}};
    wire [167:0] aux_row;
    genvar a;
    generate for (a = 0; a < 12; a = a + 1) begin : g_aux
        if (a < 4) begin : pq
            assign aux_row[14*a +: 14] = {f_pqx[18:7], a[1:0]};     // x_addr[17:6] * 4 + a
        end else begin : g_edge
            assign aux_row[14*a +: 14] = x_ar[14*(a-4) +: 14];
        end
    end endgenerate
    wire [17:0] n_v; wire [251:0] n_row; wire [89:0] n_slot; wire [2:0] n_group; wire [11:0] a_v; wire [167:0] a_row;
    wire rel_v; wire [2:0] rel_g; wire [31:0] rel_m; wire [17:0] exp_v; wire [89:0] rel_s; wire [11:0] aux_exp;
    wire [419:0] obs_row; wire [19:0] mx_exp; wire [99:0] mx_sl; wire r_flt;
    dsfd_vm_static_rsched u_rs (.ck(ck), .rst_n(rss), .su_v(f_su_rqv), .su_row(f_su_rq), .hc_v(f_hc_rqv), .hc_row(f_hc_rq),
        .aux_v(aux_v), .aux_row(aux_row), .mx_v(f_mx_rqv), .mx_row(f_mx_rq),
        .mx_expected(mx_exp), .mx_rslot(mx_sl), .sched_fault(r_flt), .n_v(n_v), .n_row(n_row), .n_slot(n_slot), .n_group(n_group), .a_v(a_v), .a_row(a_row),
        .release_v(rel_v), .release_group(rel_g), .release_mask(rel_m), .expected_v(exp_v), .release_slot(rel_s),
        .aux_expected(aux_exp), .obs_row(obs_row));
    reg pq_bad;
    always @(posedge ck) if (!rn) pq_bad <= 1'b0; else if (f_pqx[0] && (f_pqx[19] || f_pqx[6:1] != 6'd0)) pq_bad <= 1'b1;

    // ---------------------------------------------------------------- write sources
    localparam integer NSRC = 53;
    wire [3:0] lo_v; wire [55:0] lo_row; wire [2047:0] lo_d; wire [2:0] l_flt;
    reg [NSRC-1:0] s_v; reg [14*NSRC-1:0] s_row; reg [16*NSRC-1:0] s_m; reg [512*NSRC-1:0] s_d; reg [8*NSRC-1:0] s_t;
    always @* begin : p_src integer c;
        s_v = {NSRC{1'b0}}; s_row = {14*NSRC{1'b0}}; s_m = {16*NSRC{1'b0}}; s_d = {512*NSRC{1'b0}}; s_t = {8*NSRC{1'b0}};
        for (c = 0; c < 16; c = c + 1) begin
            s_v[c] = f_su_wqv[c]; s_row[14*c +: 14] = f_su_wq[14*c +: 14]; s_m[16*c +: 16] = f_su_wqm[16*c +: 16];
            s_d[512*c +: 512] = f_su_wqd[512*c +: 512]; s_t[8*c +: 8] = c[7:0];
        end
        for (c = 0; c < 8; c = c + 1) begin
            s_v[16+c] = f_hc_wqv[c]; s_row[14*(16+c) +: 14] = f_hc_wq[14*c +: 14]; s_m[16*(16+c) +: 16] = f_hc_wqm[16*c +: 16];
            s_d[512*(16+c) +: 512] = f_hc_wqd[512*c +: 512]; s_t[8*(16+c) +: 8] = 8'(16 + c);
        end
        for (c = 0; c < 4; c = c + 1) begin
            s_v[24+c] = lo_v[c]; s_row[14*(24+c) +: 14] = lo_row[14*c +: 14]; s_m[16*(24+c) +: 16] = 16'hffff;
            s_d[512*(24+c) +: 512] = lo_d[512*c +: 512]; s_t[8*(24+c) +: 8] = 8'(24 + c);
        end
        for (c = 0; c < 4; c = c + 1) begin
            s_v[28+c] = f_mx_wqv[c]; s_row[14*(28+c) +: 14] = f_mx_wq[14*c +: 14]; s_m[16*(28+c) +: 16] = f_mx_wqm[16*c +: 16];
            s_d[512*(28+c) +: 512] = f_mx_wqd[512*c +: 512]; s_t[8*(28+c) +: 8] = 8'(28 + c);
        end
        for (c = 0; c < 16; c = c + 1) begin : cap
            integer sc; sc = (c < 12) ? 32 + c : 36 + c;          // lanes 0..11 -> 32..43, 12..15 -> 48..51
            s_v[sc] = cp_v[c]; s_row[14*sc +: 14] = cp_row[14*c +: 14]; s_m[16*sc +: 16] = cp_m[16*c +: 16];
            s_d[512*sc +: 512] = cp_d[512*c +: 512]; s_t[8*sc +: 8] = 8'(sc);
        end
        for (c = 0; c < 4; c = c + 1) begin
            s_v[44+c] = cl_v[c]; s_row[14*(44+c) +: 14] = cl_row[14*c +: 14]; s_m[16*(44+c) +: 16] = cl_m[16*c +: 16];
            s_d[512*(44+c) +: 512] = cl_d[512*c +: 512]; s_t[8*(44+c) +: 8] = cl_t[8*c +: 8];
        end
        s_v[52] = wf_v; s_row[14*52 +: 14] = wf_row; s_m[16*52 +: 16] = 16'hffff; s_d[512*52 +: 512] = wf_d; s_t[8*52 +: 8] = 8'd52;
    end
    wire [31:0] wq_v; wire [447:0] wq_row; wire [511:0] wq_mask; wire [16383:0] wq_data; wire [255:0] wq_tag; wire w_flt;
    dsfd_vm_static_wsched #(.NSRC(NSRC)) u_ws (.ck_control(ck), .ck_header(ck), .ck_payload({4{ck}}),
        .ck_dispatch({16{ck}}), .ck_stage({128{ck}}), .rst_n(rss), .i_v(s_v), .i_row(s_row), .i_mask(s_m), .i_data(s_d),
        .i_tag(s_t), .wq_v(wq_v), .wq_row(wq_row), .wq_mask(wq_mask), .wq_data(wq_data), .wq_tag(wq_tag), .fault(w_flt));

    // ---------------------------------------------------------------- native memory
    wire [71:0] nat_v; wire [9215:0] nat_d; wire [127:0] grp_v; wire [16383:0] grp_d; wire [11:0] grp_id;
    wire [127:0] cm_v; wire [1151:0] cm_a; wire [511:0] cm_m; wire [1023:0] cm_t; wire [15:0] m_flt;
    dsfd_vm_static512_suhc u_mem (.ck_rscatter({4{ck}}), .ck_wcapture({128{ck}}),.ck_wscatter({16{ck}}), .ck_return({4{ck}}), .ck_bank({128{ck}}),
        .rst_n(rss), .ck_relay_req({48{ck}}), .ck_relay_rsp({48{ck}}),
        .native_rq_v(n_v), .native_rq_row(n_row), .native_rq_slot(n_slot), .native_rq_group(n_group),
        .aux_rq_v(a_v), .aux_rq_row(a_row),
        .wq_v(wq_v), .wq_row(wq_row), .wq_mask(wq_mask), .wq_data(wq_data), .wq_tag(wq_tag),
        .release_v(rel_v), .release_group(rel_g), .release_mask(rel_m),
        .native_expected_v(exp_v), .native_release_slot(rel_s),
        .native_v(nat_v), .native_data(nat_d), .group_v(grp_v), .group_data(grp_d), .group_id(grp_id),
        .commit_v(cm_v), .commit_addr(cm_a), .commit_mask(cm_m), .commit_tag(cm_t), .fault(m_flt));

    // ---------------------------------------------------------------- die output registers (P+12)
    reg o_bad;
    always @(posedge ck) begin : p_out integer p, s; reg bad;
        bad = 1'b0;
        for (p = 0; p < 18; p = p + 1)
            for (s = 1; s < 4; s = s + 1) if (nat_v[18*s + p] != nat_v[p]) bad = 1'b1;
        for (p = 20; p < 28; p = p + 1)
            for (s = 0; s < 4; s = s + 1) if (aux_exp[p-20] && !grp_v[32*s + p]) bad = 1'b1;
        for (p = 0; p < 20; p = p + 1)
            for (s = 0; s < 4; s = s + 1) if (mx_exp[p] && !grp_v[32*s + mx_sl[5*p +: 5]]) bad = 1'b1;
        if (!rn) begin t_su_rsv <= 16'd0; t_hc_rsv <= 2'd0; t_pqx[0] <= 1'b0; x_rv <= 8'd0; t_mx_rsv <= 20'd0; o_bad <= 1'b0; end
        else begin
            t_su_rsv <= nat_v[15:0]; t_hc_rsv <= nat_v[17:16];
            t_pqx[0] <= aux_exp[0] && grp_v[20] && grp_v[52] && grp_v[84] && grp_v[116];
            for (p = 0; p < 8; p = p + 1) x_rv[p] <= aux_exp[4+p] && grp_v[24+p] && grp_v[56+p] && grp_v[88+p] && grp_v[120+p];
            t_mx_rsv <= mx_exp;
            if (bad) o_bad <= 1'b1;
        end
        t_su_rs <= nat_d[8191:0]; t_hc_rs <= nat_d[9215:8192];
        t_pqx[2048:1] <= grp_d[512*20 +: 2048];
        for (p = 0; p < 20; p = p + 1) t_mx_rs[512*p +: 512] <= grp_d[512*mx_sl[5*p +: 5] +: 512];
        x_rd <= grp_d[512*24 +: 4096];
    end

    // ---------------------------------------------------------------- engine 12 + static native ops
    wire v_cv; wire [83:0] v_cd; reg v_dv; reg [7:0] v_dt; reg op_bad;
    wire svc_flt = w_flt | |m_flt | |l_flt | pq_bad | o_bad | op_bad | r_flt | x_flt;
    dsfd_vm_seq_static u_seq (.ck(ck), .rst(rss), .c_cmd(c_cmd), .c_done(c_done), .c_st(c_st),
        .o_cv(cm_v), .o_ca(cm_a), .o_cm(cm_m), .o_rv({2'b00, a_v, n_v}), .o_rr({28'd0, obs_row}),
        .v_cv(v_cv), .v_cd(v_cd), .v_dv(v_dv), .v_dt(v_dt), .v_flt(svc_flt),
        .t_inp_su(t_inp_su), .t_inp_hc(t_inp_hc));
    wire [2:0] v_code = v_cd[30:28];
    wire larm_v = v_cv && v_code == 3'd6 && v_cd[27:24] != 4'd7;      // group 7 = collective landing (xio)
    assign nf_v = v_cv; assign nf_d = v_cd;
    always @(posedge ck) begin
        if (!rn) begin v_dv <= 1'b0; op_bad <= 1'b0; end
        else begin
            v_dv <= v_cv;                                  // fixed: every native op retires one edge after its forward
            if (v_cv && (v_code == 3'd5 || v_code == 3'd7 ||
                (v_code == 3'd6 && v_cd[27:24] == 4'd7))) op_bad <= 1'b1; // legacy collective ops removed
        end
        v_dt <= {v_cd[83], v_cd[6:0]};
    end
    dsfd_vm_static_landing u_land (.ck(ck), .rst_n(rss), .larm_v(larm_v), .larm_g(v_cd[27:24]), .larm_base(v_cd[20:7]),
        .i_v(l_v), .i_d(l_d), .o_v(lo_v), .o_row(lo_row), .o_d(lo_d), .fault(l_flt));
    assign vm_fault = svc_flt;
endmodule
`default_nettype wire

dsfd_vm_static_rsched.sv.text:
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------
// dsfd_vm_static_rsched (claude S81 VM owner r8, 2026-10-14): the fixed-rule READ schedule of the static VM, in front of
// dsfd_vm_static512_suhc (FSR -> 2 relay levels -> 128 real 1R1W SRAM banks -> return store -> native return map).
// No ready, credit, queue, arbitration or schedule extension: every output is a fixed function of the compiled request
// pattern, delayed by a fixed number of edges.
//   P     pin register: SU 16 + HC 2 native read requests (row 14), 12 auxiliary requests (row 14), sampled at edge P.
//         RETURN SLOT (fixed function, the FSR legality table): SU p (2..15) -> slot p; SU0 -> row[1:0];
//         SU1 -> row[1:0] unless that slot is taken this edge by SU0 / SU2 / SU3, then 4 + row[1:0];
//         HC h -> 16 + row[1:0]; aux a -> 20 + a.  Collisions / illegal low bits are FSR schedule faults.
//         GROUP = free-running edge counter mod 8 (every edge is its own return group; two parity buffers suffice
//         because every group is released exactly 10 edges after its FSR sample).
//   P+1   FSR samples (E0 of the static512 timeline)            P+11  fixed release (E0 + 10): return store -> o_v
//   native_v / native_data / aux group rows are valid in the cycle after P+11 (a die output register samples at P+12).
//   The release chain is the request vector itself delayed 10 edges: release_mask = the slots of that edge's requests,
//   native_expected_v / native_release_slot = that edge's SU/HC requests and slots, aux_expected = its aux requests.
//   A row missing at its release edge is a fault of the return leaf (never waited for).
// ---------------------------------------------------------------------------------------------------------------
module dsfd_vm_static_rsched (
    input  wire          ck, rst_n,
    input  wire [15:0]   su_v,  input wire [223:0] su_row,
    input  wire [1:0]    hc_v,  input wire [27:0]  hc_row,
    input  wire [11:0]   aux_v, input wire [167:0] aux_row,
    // Engram MIX4 endpoint (dsfd_engram_mix4_c rq_v / rq_row): 20 reads an edge.  RETURN SLOT (fixed function): lane i
    // -> slot {G(i), row[1:0]}, G = 0, 1, 2, 3 for lanes 0..15 (SU ports 4G .. 4G+3), G = 5 for lanes 16..19 (aux 0..3);
    // the MIX4 layout's rows (row[1:0] = lane[1:0] ^ beat[1:0]) give each group four distinct low bits.  Slot s rides
    // logical port s (0..15: SU ports, 20..31: aux s - 20; HC slots 16..19 are never used by MIX).  The compiler gives
    // MIX its own edges: a port carrying an SU/HC/aux request and a MIX request on one edge is a schedule fault.
    input  wire [19:0]   mx_v,  input wire [279:0] mx_row,
    output wire [19:0]   mx_expected, output wire [99:0] mx_rslot,
    output reg           sched_fault,
    output reg  [17:0]   n_v,   output reg [251:0] n_row, output reg [89:0] n_slot, output reg [2:0] n_group,
    output reg  [11:0]   a_v,   output reg [167:0] a_row,
    output wire          release_v, output wire [2:0] release_group, output wire [31:0] release_mask,
    output wire [17:0]   expected_v, output wire [89:0] release_slot, output wire [11:0] aux_expected,
    output wire [14*30-1:0] obs_row       // logical rows of the FSR-sampled requests (engine early-read assertion)
);
    reg [1:0] rr;
    always @(posedge ck or negedge rst_n) if (!rst_n) rr <= 2'b00; else rr <= {rr[0], 1'b1};
    wire rn = rr[1];

    reg [17:0] qv; reg [251:0] qr; reg [11:0] qav; reg [167:0] qar; reg [2:0] grp;
    reg [19:0] qmv; reg [279:0] qmr; reg [99:0] qms;
    always @* begin : p_mxs integer i;
        for (i = 0; i < 20; i = i + 1)
`ifdef OT_VM_RSCHED_MUT_MIXSLOT
            qms[5*i +: 5] = {3'(i >> 2), qmr[14*i +: 2]};          // MUTANT: lanes 16..19 onto the HC slots 16..19
`else
            qms[5*i +: 5] = {(i < 16) ? 3'(i >> 2) : 3'd5, qmr[14*i +: 2]};
`endif
    end
    always @(posedge ck) begin
        if (!rn) begin qv <= 18'd0; qav <= 12'd0; grp <= 3'd0; qmv <= 20'd0; end
        else begin qv <= {hc_v, su_v}; qav <= aux_v; grp <= grp + 3'd1; qmv <= mx_v; end
        qr <= {hc_row, su_row}; qar <= aux_row; qmr <= mx_row;
    end
    // MIX merge onto the 30 logical ports (fixed function of the compiled slots)
    reg [17:0] pv; reg [251:0] pr; reg [11:0] pav; reg [167:0] par; reg [29:0] mo; reg m_bad;
    always @* begin : p_merge integer i; reg [4:0] s; integer port; reg hc0;
        pv = qv; pr = qr; pav = qav; par = qar; mo = 30'd0; m_bad = 1'b0; hc0 = 1'b0;
        for (i = 0; i < 20; i = i + 1) if (qmv[i]) begin
            s = qms[5*i +: 5];
            if (s < 5'd16) port = s;
            else if (s < 5'd20) begin port = hc0 ? 17 : 16; hc0 = 1'b1; end
            else port = 18 + (s - 20);
            if (s[1:0] != qmr[14*i +: 2]) m_bad = 1'b1;              // slot lane = row[1:0] (FSR lane rule)
            if (port < 18) begin
                if (pv[port] || mo[port]) m_bad = 1'b1;
                pv[port] = 1'b1; pr[14*port +: 14] = qmr[14*i +: 14];
            end else begin
                if (pav[port-18] || mo[port]) m_bad = 1'b1;
                pav[port-18] = 1'b1; par[14*(port-18) +: 14] = qmr[14*i +: 14];
            end
            mo[port] = 1'b1;
        end
    end

    reg [89:0] slot;
    always @* begin : p_slot integer p; reg [1:0] l0, l1;
        for (p = 2; p < 16; p = p + 1) slot[5*p +: 5] = p[4:0];
        l0 = pr[0 +: 2]; l1 = pr[14 +: 2];
        slot[0 +: 5] = {3'd0, l0};
`ifdef OT_VM_RSCHED_MUT_SLOT
        slot[5 +: 5] = {3'd0, l1};                      // MUTANT: SU1 never moves off a taken slot
`else
        slot[5 +: 5] = ((pv[0] && l0 == l1) || (pv[2] && l1 == 2'd2) || (pv[3] && l1 == 2'd3)) ? {3'd1, l1} : {3'd0, l1};
`endif
        slot[80 +: 5] = {3'd4, pr[14*16 +: 2]};
        slot[85 +: 5] = {3'd4, pr[14*17 +: 2]};
    end
    // every MIX request must land on exactly its compiler slot (SU0 / SU1 / HC slot functions included)
    reg s_bad;
    always @* begin : p_mchk integer i; reg [4:0] s; integer port; reg hc0;
        s_bad = 1'b0; hc0 = 1'b0;
        for (i = 0; i < 20; i = i + 1) if (qmv[i]) begin
            s = qms[5*i +: 5];
            if (s < 5'd16) port = s; else if (s < 5'd20) begin port = hc0 ? 17 : 16; hc0 = 1'b1; end else port = 18 + (s - 20);
            if (port < 18 && slot[5*port +: 5] != s) s_bad = 1'b1;
        end
    end
    always @(posedge ck) if (!rn) sched_fault <= 1'b0; else if (m_bad || s_bad) sched_fault <= 1'b1;

    // FSR pin feed (registered: the FSR's own pin stage samples these at P+1 -- this stage is the die pin register)
    always @* begin n_v = pv; n_row = pr; n_slot = slot; n_group = grp; a_v = pav; a_row = par; end
    assign obs_row = {par, pr};

    // release chain: stage k holds the FSR sample of edge (P+1)+(k-1); stage 10 is sampled by the return leaves at E0+10
    // (the static512 template: request E0, bank E4..E6, response relays E7/E8, return store E9, fixed release E10)
    reg [17:0] dv [1:11]; reg [89:0] ds [1:11]; reg [2:0] dg [1:10]; reg [11:0] da [1:11]; reg [29:0] dm [1:11];
    reg [19:0] dxv [1:11]; reg [99:0] dxs [1:11];
    always @(posedge ck) begin : p_chain integer k;
        if (!rn) for (k = 1; k <= 11; k = k + 1) begin dv[k] <= 18'd0; da[k] <= 12'd0; dm[k] <= 30'd0; dxv[k] <= 20'd0; end
        else begin
            dv[1] <= pv; ds[1] <= slot; dg[1] <= grp; da[1] <= pav; dm[1] <= mo; dxv[1] <= qmv; dxs[1] <= qms;
            for (k = 2; k <= 10; k = k + 1) begin dv[k] <= dv[k-1]; ds[k] <= ds[k-1]; dg[k] <= dg[k-1]; da[k] <= da[k-1]; end
            for (k = 2; k <= 11; k = k + 1) begin dm[k] <= dm[k-1]; dxv[k] <= dxv[k-1]; dxs[k] <= dxs[k-1]; end
            dv[11] <= dv[10]; ds[11] <= ds[10]; da[11] <= da[10];
        end
    end
    reg [31:0] rm;
    always @* begin : p_mask integer p;
        rm = 32'd0;
        for (p = 0; p < 18; p = p + 1) if (dv[10][p]) rm[ds[10][5*p +: 5]] = 1'b1;
        for (p = 0; p < 12; p = p + 1) if (da[10][p]) rm[20 + p] = 1'b1;
    end
    assign release_v = |dv[10] | |da[10];
    assign release_group = dg[10];
    assign release_mask = rm;
    // the return leaves' o_v is registered AT the release edge: the native map's expected/slot selectors and the aux
    // expectation are the same requests one stage later (held through the cycle that follows the release edge)
    // MIX-owned ports are released with the group but are not native SU/HC / aux returns
    assign expected_v = dv[11] & ~dm[11][17:0];
    assign release_slot = ds[11];
    assign aux_expected = da[11] & ~dm[11][29:18];
    assign mx_expected = dxv[11];
    assign mx_rslot = dxs[11];
endmodule
`default_nettype wire

dsfd_vm_static_wcontrol.sv.text:
`timescale 1ns/1ps
`default_nettype none
// Actual 296-flop control leaf. Owns prefix lane logic, fixed drain calendar,
// fault observations and reset release on one native clock root. No arbitration,
// ready, runtime scheduling or stage addition. The parent is wires only.
module dsfd_vm_static_wcontrol #(parameter integer NSRC=53)(
 input wire ck_control,rst_n,
 input wire [NSRC-1:0] pv,input wire [14*NSRC-1:0] pr,
 input wire [95:0] cap_v,input wire [2:0] header_epoch,input wire [11:0] payload_epoch,
 output reg [2*NSRC-1:0] lane,output reg [NSRC-1:0] lv,
 output reg [31:0] dr_v,output reg [63:0] dr_s,output reg [2:0] own
);
    reg [1:0] rr;
    always @(posedge ck_control or negedge rst_n) if (!rst_n) rr <= 2'b00; else rr <= {rr[0], 1'b1};
    wire rn = rr[1];

    reg [2:0] control_epoch;
    always @(posedge ck_control) if (!rn) control_epoch <= 3'd0; else control_epoch <= control_epoch + 3'd1;
    wire phase_bad = (header_epoch != control_epoch) ||
        (payload_epoch[2:0] != control_epoch) || (payload_epoch[5:3] != control_epoch) ||
        (payload_epoch[8:6] != control_epoch) || (payload_epoch[11:9] != control_epoch);
    reg lane_bad;
    always @* begin : p_lane integer c, d; reg [4:0] bc, bd; reg [5:0] n;
        lane_bad = 1'b0;
        for (c = 0; c < NSRC; c = c + 1) begin
            bc = pr[14*c +: 5] ^ {pr[14*c+5 +: 3], 2'b00};
            n = 6'd0;
            for (d = 0; d < c; d = d + 1) begin
                bd = pr[14*d +: 5] ^ {pr[14*d+5 +: 3], 2'b00};
                if (pv[d] && bd == bc) n = n + 6'd1;
            end
`ifdef OT_VM_WSCHED_MUT_LANE
            lane[2*c +: 2] = 2'd0;                    // MUTANT: every record on lane 0 (dispatch duplicate)
`else
            lane[2*c +: 2] = (n > 6'd2) ? 2'd3 : n[1:0];
`endif
            lv[c] = pv[c] && n <= 6'd2;
            if (pv[c] && n > 6'd2) lane_bad = 1'b1;
        end
    end

    // ---------------------------------------------------------------- fixed drain rule (from slice 0's captures)
    // h1 = dispatch o_v sampled at P+3 (the storage capture edge): lane 0 drains into the P+4 scatter sample, h2 lane 1
    // at P+5, h3 lane 2 at P+6
    reg [95:0] h1, h2, h3; reg drain_bad;
    always @(posedge ck_control) begin
        if (!rn) begin h1 <= 96'd0; h2 <= 96'd0; h3 <= 96'd0; end
        else begin h1 <= cap_v; h2 <= h1; h3 <= h2; end
    end
    always @* begin : p_drain integer k; reg l0, l1, l2;
        drain_bad = 1'b0;
        for (k = 0; k < 32; k = k + 1) begin
            l0 = h1[3*k]; l1 = h2[3*k+1]; l2 = h3[3*k+2];
`ifdef OT_VM_WSCHED_MUT_DRAIN
            l1 = h1[3*k+1];                              // MUTANT: lane 1 drains one edge early (P+4, not P+5)
`endif
            dr_v[k] = l0 | l1 | l2;
            dr_s[2*k +: 2] = l0 ? 2'd0 : l1 ? 2'd1 : 2'd2;
            if ((l0 && l1) || (l0 && l2) || (l1 && l2)) drain_bad = 1'b1;
        end
    end

    always @(posedge ck_control) if (!rn) own <= 3'b000; else own <= own | {phase_bad, drain_bad, lane_bad};
endmodule
`default_nettype wire

ot_s81_vm_x34.sv.text:
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------
// ot_s81_vm_x34 (claude S81 VM owner r8, 2026-10-14): FIXED-PHASE serial (0.9 GHz) -> stream (1.2 GHz) word transfer
// on the common 3:4 epoch (3 serial = 4 stream cycles = 3.333 ns, both clocks from one source; the owner's static rule:
// no handshake, no FIFO pointers, no credit, no ready).  Every serial cycle's word {v, d} is written into bank
// k = serial phase (0..2); the stream side reads bank 0 / 1 / 2 at fixed stream edges 2 / 3 / 4 (= 0 of the next epoch)
// of the epoch the word was written in.  Launch -> capture is >= 1.111 ns on every bank and the word stays in its
// bank for 3.333 ns (written once per epoch), so every arc is a full-period related-clock transfer (no synchroniser:
// phase-locked clocks; STA owns the arcs with the epoch multicycle).  Stream edge 1 of every epoch carries no word.
// Latency (fixed): serial word sampled at serial edge k of epoch n -> o_v/o_d registered at stream edge 2 + k of n.
// STARTUP CONTRACT: both resets are released so that the first rising edges after release are the epoch's serial edge
// 0 and stream edge 0 (the common-epoch divider, aa670a062 family).  ALIGNMENT ASSERTION: every bank entry carries the
// serial epoch parity; the stream side compares it with its own epoch parity on every read after one warm-up epoch;
// a slipped epoch -> sticky fault; PHASE ASSERTION: a serial phase marker (high in serial cycle 1 only) must be
// sampled high by stream edge 2 and low by stream edges 0 / 1 / 3: any sub-epoch misalignment -> sticky fault
// (never a re-timed transfer).
// ---------------------------------------------------------------------------------------------------------------
module ot_s81_vm_x34 #(parameter integer W = 512) (
    input  wire         s_ck, s_rst_n,
    input  wire         s_v, input wire [W-1:0] s_d,
    input  wire         t_ck, t_rst_n,
    output reg          o_v, output reg [W-1:0] o_d,
    output reg          fault
);
    // ---- serial side
    reg [1:0] sp; reg se;               // phase of the cycle that FOLLOWS the last edge; epoch parity
    reg [W:0] bank0, bank1, bank2; reg [2:0] bpar;
    reg s_mark;                         // phase marker: high exactly in serial cycle 1 of every epoch ([1.111, 2.222) ns)
    always @(posedge s_ck or negedge s_rst_n)
        if (!s_rst_n) begin sp <= 2'd2; se <= 1'b0; bpar <= 3'b000; s_mark <= 1'b0; end   // first edge after release = epoch edge 0
        else begin
            s_mark <= sp == 2'd0;           // set by serial edge 1, cleared by serial edge 2
            // the edge that ends cycle sp writes bank (sp + 1) mod 3 (edge 0 of the epoch writes bank 0)
            case (sp)
                2'd2: begin bpar[0] <= ~se; end
                2'd0: begin bpar[1] <= se; end
                default: begin bpar[2] <= se; end
            endcase
            if (sp == 2'd2) begin sp <= 2'd0; se <= ~se; end else sp <= sp + 2'd1;
        end
    // data banks (no reset: the parity and v bit gate their use)
    always @(posedge s_ck) begin
        case (sp)
            2'd2: bank0 <= {s_v, s_d};
            2'd0: bank1 <= {s_v, s_d};
            default: bank2 <= {s_v, s_d};
        endcase
    end
    // ---- stream side
    reg [1:0] tp; reg te; reg warm; reg mk;    // tp = index of the last stream edge (3 at reset: the next edge is epoch edge 0)
    always @(posedge t_ck or negedge t_rst_n)
        if (!t_rst_n) begin tp <= 2'd3; te <= 1'b0; warm <= 1'b0; o_v <= 1'b0; fault <= 1'b0; mk <= 1'b0; end
        else begin
            tp <= tp + 2'd1;
            // PHASE ASSERTION: the marker is sampled high by stream edge 2 only (0.557 ns after serial edge 1), low by
            // edges 0 / 1 / 3; mk holds the previous edge's sample, so after edge 2 (tp == 2) mk must be 1, else 0
            mk <= s_mark;
            if (warm && mk != (tp == 2'd2)) fault <= 1'b1;
            if (tp == 2'd3) begin te <= ~te; warm <= 1'b1; end
            case (tp)
`ifdef OT_VM_X34_MUT_PHASE
                2'd0: begin o_v <= bank0[W]; if (warm && bpar[0] != te) fault <= 1'b1; end     // MUTANT: one stream edge early
`else
                2'd1: begin o_v <= bank0[W]; if (warm && bpar[0] != te) fault <= 1'b1; end
`endif
                2'd2: begin o_v <= bank1[W]; if (warm && bpar[1] != te) fault <= 1'b1; end
                2'd3: begin o_v <= bank2[W]; if (warm && bpar[2] != te) fault <= 1'b1; end
                default: o_v <= 1'b0;
            endcase
        end
    always @(posedge t_ck)
        case (tp)
`ifdef OT_VM_X34_MUT_PHASE
            2'd0: o_d <= bank0[W-1:0];
`else
            2'd1: o_d <= bank0[W-1:0];
`endif
            2'd2: o_d <= bank1[W-1:0];
            2'd3: o_d <= bank2[W-1:0];
            default: ;
        endcase
endmodule
`default_nettype wire

dsfd_vm_static_suhc_fsr.sv.text:
`timescale 1ns/1ps
// Native endpoint pin register + compiler permutation + actual hashed bank FSR.
// Native ports0..15=SU,16..17=HC; auxiliary ports map return slots20..31.
// Compiler supplies native return slots every issue edge. Restricted choices
// keep14wide SU lanes wired, sparseSU0/1 and HC allow per-beat permutation.
// Replaces the old generic rscatter's pin stage, so E0pins->E1bank outputs.
module dsfd_vm_static_suhc_fsr(
 input wire ck,rst_n,input wire [17:0] i_v,input wire [251:0] i_row,
 input wire [89:0] i_slot,input wire [2:0] i_group,
 input wire [11:0] i_aux_v,input wire [167:0] i_aux_row,
 output reg [31:0] o_v,output reg [287:0] o_addr,output reg [255:0] o_tag,
 output reg fault
);
 reg [1:0] reset_release;
 always @(posedge ck or negedge rst_n)if(!rst_n)reset_release<=0;else reset_release<={reset_release[0],1'b1};
 wire rn=reset_release[1];
 reg [29:0] v;reg [419:0] row;reg [89:0] slots;reg [2:0] group;
 always @(posedge ck or negedge rn)if(!rn)v<=0;else v<={i_aux_v,i_v};
 always @(posedge ck)begin row<={i_aux_row,i_row};slots<=i_slot;group<=i_group;end
 reg bad;integer p,q,s,t;reg [4:0] bank;reg legal;
 always @*begin
  bad=0;bank=0;legal=1;s=0;t=0;
  for(p=0;p<30;p=p+1)if(v[p])begin
   s=p<18?slots[5*p+:5]:p+2;legal=1;
   if(p==0)legal=s<4;else if(p==1)legal=s<8;
   else if(p<16)legal=s==p;else if(p<18)legal=s>=16 &&s<20;
   if(!legal || (s%4)!=row[14*p+:2])bad=1;
   for(q=p+1;q<30;q=q+1)if(v[q])begin
    t=q<18?slots[5*q+:5]:q+2;
    if(t==s)bad=1;
   end
  end
 end
 wire [31:0] bv,dup;
 genvar g;generate for(g=0;g<32;g=g+1)begin:bank_route
  reg hit,d;reg [8:0] a;reg [7:0] tag;integer j,slot;reg [4:0] b;
  always @*begin
   hit=0;d=0;a=0;tag=0;slot=0;b=0;
   for(j=0;j<30;j=j+1)begin
    slot=j<18?slots[5*j+:5]:j+2;
    b=row[14*j+:5]^{row[14*j+5+:3],2'b00};
    if(v[j] && b==g)begin
     if(hit)d=1;hit=1;a=a|row[14*j+5+:9];tag=tag|{group,5'(slot)};
    end
   end
  end
  assign bv[g]=hit&&!d;assign dup[g]=d;
  always @(posedge ck)begin o_addr[9*g+:9]<=a;
`ifdef OT_VM_SUHC_FSR_MUT_TAG
   o_tag[8*g+:8]<=tag^8'h1;
`else
   o_tag[8*g+:8]<=tag;
`endif
  end
 end endgenerate
 always @(posedge ck or negedge rn)
  if(!rn)begin o_v<=0;fault<=0;end else begin o_v<=bv;fault<=fault|bad|(|dup);end
endmodule

dsfd_sp_vm_static.sv.text:
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------
// dsfd_sp_vm (STATIC revision s2, claude S81 VM owner r9, 2026-10-14): the S81 layer-die VM master under its die
// name, a cluster over real RTL only.  s2 binds ALL 40 die ports of the S-BIND v20 list (s1 bound 31):
//   dsfd_vm_static_core  stream 1.2 GHz: 128 real SRAM banks, fixed-rule read / write service, engine 12, static LARM
//   dsfd_vm_static_cap   capture face: 16 static row-assembly lanes (serial) + 16 fixed-phase 3:4 transfers
//   dsfd_vm_static_wfc   WFC kit VM channels: one write + one read pair a serial cycle, constant grants, fixed return
//   dsfd_vm_static_xio   outbound row streams (collective records, scan queries, gather phase words), collective
//                        landing + fixed source-row service / phase-stage assertions
//   ot_s81_vm_x34 x 3    serial landing producers (selector, collector, HBM scan service SW)
// Owner rules 2026-10-14T18:59 / 19:12: static cycle schedule, no credits / backpressure / ready-driven issue; all
// on-chip execution real hardware.  Every port lands on real RTL; no functional port is tied.
//
// PORTS (directions the VM's; widths = the die nets; domain: S serial ck/rst 0.9 GHz, T stream cks/rss 1.2 GHz):
//   ck rst (S) / cks rss (T)   STARTUP CONTRACT: both resets released on the common 3:4 epoch (x34 / x43 headers)
//   c_cmd 85 / c_done 9 / c_st 2 (T)    sequencer engine 12 (done = command pin + 6); t_inp_su / t_inp_hc (T)
//   SU 16 rd + 16 wr / HC 2 rd + 8 wr row slots (T), f_pqx 20 -> t_pqx 2049 (T)              L 12 reads
//   sel 515 / col 515 / aSW 1027 (S)      landing producers (static LARM groups 5 / 6 / 0)
//   f_capture 13376 (S)                   dsfd_sp_capture_c t_vm: static capture rows (write sources 32..43, 48..51)
//   f_wfc 560 (S) -> t_wfc 1029 (S)       dsfd_wfc_stg VM channels (write source 52, aux reads 8..11)
//   f_collective 2204 (T)                 four compiler-addressed static row writes (sources 44..47)
//   f_crq 15 / t_crs 513 (T)              collective fixed-latency source-row service; no credits or room
//   t_gather 512 (S) / f_xgo 11 (T)       -> dsfd_sp_gather_c f_vm phase words (STREAM dest 1); xgo = assertion feed
//   qSW 513 (S) / qSWs 3 (S)              -> scan service query lane end block (STREAM dest 0); qSWs = assertion feed
// Engram MIX4 (20R/4W, dsfd_engram_mix4_c) is built in the core; its die ports appear under
// +define+DSFD_SP_VM_MIX4 once the die wires the MIX4 slot (no die net today: without the define the core's MIX
// inputs are held idle and its outputs unread, the MIX function is absent from this die revision, not stubbed).
// ---------------------------------------------------------------------------------------------------------------
module dsfd_sp_vm (
    input  wire [0:0]    ck, rst, cks, rss,
    input  wire [84:0]   c_cmd, output wire [8:0] c_done, output wire [1:0] c_st,
    output wire [0:0]    t_inp_su, t_inp_hc,
    input  wire [15:0]   f_su_rqv, input wire [223:0] f_su_rq, output wire [15:0] t_su_rsv, output wire [8191:0] t_su_rs,
    input  wire [15:0]   f_su_wqv, input wire [223:0] f_su_wq, input wire [255:0] f_su_wqm, input wire [8191:0] f_su_wqd,
    input  wire [1:0]    f_hc_rqv, input wire [27:0] f_hc_rq, output wire [1:0] t_hc_rsv, output wire [1023:0] t_hc_rs,
    input  wire [7:0]    f_hc_wqv, input wire [111:0] f_hc_wq, input wire [127:0] f_hc_wqm, input wire [4095:0] f_hc_wqd,
    input  wire [19:0]   f_pqx, output wire [2048:0] t_pqx,
    input  wire [514:0]  sel, col,
    input  wire [1026:0] aSW,
    input  wire [13375:0] f_capture,
    input  wire [559:0]  f_wfc, output wire [1028:0] t_wfc,
    input  wire [2203:0] f_collective, input wire [14:0] f_crq, output wire [512:0] t_crs,
    output wire [511:0]  t_gather, input wire [10:0] f_xgo,
    output wire [512:0]  qSW, input wire [2:0] qSWs
`ifdef DSFD_SP_VM_MIX4
    , input  wire [19:0] f_mx_rqv, input wire [279:0] f_mx_rq, output wire [19:0] t_mx_rsv, output wire [10239:0] t_mx_rs
    , input  wire [3:0]  f_mx_wqv, input wire [55:0] f_mx_wq, input wire [63:0] f_mx_wqm, input wire [2047:0] f_mx_wqd
`endif
);
`ifndef DSFD_SP_VM_MIX4
    wire [19:0] f_mx_rqv = 20'd0; wire [279:0] f_mx_rq = 280'd0; wire [19:0] t_mx_rsv; wire [10239:0] t_mx_rs;
    wire [3:0] f_mx_wqv = 4'd0; wire [55:0] f_mx_wq = 56'd0; wire [63:0] f_mx_wqm = 64'd0; wire [2047:0] f_mx_wqd = 2048'd0;
`endif
    // ---------------------------------------------------------------- serial -> stream landing transfers
    wire xs_v, xc_v, xw_v; wire [513:0] xs_d, xc_d; wire [1025:0] xw_d; wire [2:0] x_al;
    ot_s81_vm_x34 #(.W(514)) u_xsel (.s_ck(ck[0]), .s_rst_n(rst[0]), .s_v(sel[0]), .s_d(sel[514:1]),
        .t_ck(cks[0]), .t_rst_n(rss[0]), .o_v(xs_v), .o_d(xs_d), .fault(x_al[0]));
    ot_s81_vm_x34 #(.W(514)) u_xcol (.s_ck(ck[0]), .s_rst_n(rst[0]), .s_v(col[0]), .s_d(col[514:1]),
        .t_ck(cks[0]), .t_rst_n(rss[0]), .o_v(xc_v), .o_d(xc_d), .fault(x_al[1]));
    ot_s81_vm_x34 #(.W(1026)) u_xsw (.s_ck(ck[0]), .s_rst_n(rst[0]), .s_v(aSW[0]), .s_d(aSW[1026:1]),
        .t_ck(cks[0]), .t_rst_n(rss[0]), .o_v(xw_v), .o_d(xw_d), .fault(x_al[2]));
    reg p_bad;
    always @(posedge cks[0] or negedge rss[0])
        if (!rss[0]) p_bad <= 1'b0;
        else if ((xs_v && !xs_d[512]) || (xc_v && !xc_d[512]) || (xw_v && !xw_d[1024]) ||
                 (xs_v && xs_d[513]) || (xc_v && xc_d[513]) || (xw_v && xw_d[1025])) p_bad <= 1'b1;
    // ---------------------------------------------------------------- edge services
    wire [15:0] cp_v; wire [223:0] cp_row; wire [255:0] cp_m; wire [8191:0] cp_d; wire cap_f;
    dsfd_vm_static_cap u_cap (.ck(ck[0]), .rst(rst[0]), .cks(cks[0]), .rss(rss[0]), .f_capture(f_capture),
        .w_v(cp_v), .w_row(cp_row), .w_m(cp_m), .w_d(cp_d), .fault(cap_f));
    wire wf_v; wire [13:0] wf_row; wire [511:0] wf_d; wire [3:0] wa_v; wire [55:0] wa_row; wire wfc_f;
    wire [7:0] x_rv; wire [4095:0] x_rd; wire [3:0] xa_v; wire [55:0] xa_row; wire xio_f; wire vm_fault;
    wire n_v; wire [83:0] n_d;
    wire [3:0] cl_v; wire [55:0] cl_row; wire [2047:0] cl_d; wire [63:0] cl_m; wire [31:0] cl_t;
    dsfd_vm_static_wfc u_wfc (.ck(ck[0]), .rst(rst[0]), .cks(cks[0]), .rss(rss[0]), .f_wfc(f_wfc), .t_wfc(t_wfc),
        .w_v(wf_v), .w_row(wf_row), .w_d(wf_d), .a_v(wa_v), .a_row(wa_row), .e_v(x_rv[7:4]), .e_d(x_rd[4095:2048]),
        .vm_fault(vm_fault), .fault(wfc_f));
    dsfd_vm_static_xio u_xio (.cks(cks[0]), .rss(rss[0]), .ck(ck[0]), .rst(rst[0]), .n_v(n_v), .n_d(n_d),
        .a_v(xa_v), .a_row(xa_row), .e_v(x_rv[3:0]), .e_d(x_rd[2047:0]),
        .f_collective(f_collective), .f_crq(f_crq), .t_crs(t_crs),
        .w_v(cl_v), .w_row(cl_row), .w_d(cl_d), .w_m(cl_m), .w_t(cl_t),
        .t_gather(t_gather), .f_xgo(f_xgo), .qSW(qSW), .qSWs(qSWs), .fault(xio_f));
    // edge faults -> engine 12 legacy-fault input (c_st[0]); serial levels registered once in the stream domain
    reg e_flt;
    always @(posedge cks[0] or negedge rss[0]) if (!rss[0]) e_flt <= 1'b0; else if (cap_f | wfc_f | xio_f) e_flt <= 1'b1;
    dsfd_vm_static_core u_core (.cks(cks[0]), .rss(rss[0]), .c_cmd(c_cmd), .c_done(c_done), .c_st(c_st),
        .t_inp_su(t_inp_su[0]), .t_inp_hc(t_inp_hc[0]),
        .f_su_rqv(f_su_rqv), .f_su_rq(f_su_rq), .t_su_rsv(t_su_rsv), .t_su_rs(t_su_rs),
        .f_su_wqv(f_su_wqv), .f_su_wq(f_su_wq), .f_su_wqm(f_su_wqm), .f_su_wqd(f_su_wqd),
        .f_hc_rqv(f_hc_rqv), .f_hc_rq(f_hc_rq), .t_hc_rsv(t_hc_rsv), .t_hc_rs(t_hc_rs),
        .f_hc_wqv(f_hc_wqv), .f_hc_wq(f_hc_wq), .f_hc_wqm(f_hc_wqm), .f_hc_wqd(f_hc_wqd),
        .f_pqx(f_pqx), .t_pqx(t_pqx),
        .x_av({wa_v, xa_v}), .x_ar({wa_row, xa_row}), .x_rv(x_rv), .x_rd(x_rd), .nf_v(n_v), .nf_d(n_d),
        .f_mx_rqv(f_mx_rqv), .f_mx_rq(f_mx_rq), .t_mx_rsv(t_mx_rsv), .t_mx_rs(t_mx_rs),
        .f_mx_wqv(f_mx_wqv), .f_mx_wq(f_mx_wq), .f_mx_wqm(f_mx_wqm), .f_mx_wqd(f_mx_wqd),
        .l_v({xc_v, xs_v, xw_v, xw_v}), .l_d({xc_d[511:0], xs_d[511:0], xw_d[1023:512], xw_d[511:0]}),
        .cp_v(cp_v), .cp_row(cp_row), .cp_m(cp_m), .cp_d(cp_d), .cl_v(cl_v), .cl_row(cl_row), .cl_m(cl_m), .cl_d(cl_d), .cl_t(cl_t),
        .wf_v(wf_v), .wf_row(wf_row), .wf_d(wf_d),
        .x_flt(|x_al | p_bad | e_flt), .vm_fault(vm_fault));
endmodule
`default_nettype wire

dsfd_vm_static_wstage128.sv.text:
`timescale 1ns/1ps
// Compiler-indexed bank-local write storage. No queue head/tail, arbiter,
// credits, ready, or retry. Up to3 captures target distinct explicit slots.
// The compiler selects the exact drain edge/slot, visible combinationally to
// the receiving scatter input pins BEFORE that edge. CaptureE -> earliest
// scatter sampleE+1. Storage can be reused on the same edge it is drained.
module dsfd_vm_static_wstage128 #(parameter integer DEPTH=3)(
 input wire ck,rst_n,
 input wire [2:0] capture_v,input wire [5:0] capture_slot,
 input wire [41:0] capture_row,input wire [11:0] capture_mask,
 input wire [383:0] capture_data,input wire [23:0] capture_tag,
 input wire drain_v,input wire [1:0] drain_slot,
 output wire o_v,output reg [13:0] o_row,output reg [3:0] o_mask,
 output reg [127:0] o_data,output reg [7:0] o_tag,output reg fault
);
 reg [1:0] release_reset;
 always @(posedge ck or negedge rst_n)
  if(!rst_n)release_reset<=0;else release_reset<={release_reset[0],1'b1};
 wire rn=release_reset[1];
 reg [DEPTH-1:0] valid,valid_n;reg bad;
 reg [13:0] rows[0:DEPTH-1];reg [3:0] masks[0:DEPTH-1];
 reg [127:0] words[0:DEPTH-1];reg [7:0] tags[0:DEPTH-1];
 assign o_v=drain_v && drain_slot<DEPTH && valid[drain_slot];
 always @*begin
  o_row=0;o_mask=0;o_data=0;o_tag=0;
  for(integer s=0;s<DEPTH;s=s+1)if(drain_slot==s)begin
   o_row=rows[s];o_mask=masks[s];o_data=words[s];o_tag=tags[s];
  end
 end
 always @*begin
  valid_n=valid;bad=0;
  if(drain_v)begin
   if(drain_slot>=DEPTH)bad=1;
   else begin if(!valid[drain_slot])bad=1;valid_n[drain_slot]=0;end
  end
  for(integer c=0;c<3;c=c+1)if(capture_v[c])begin
   if(capture_slot[2*c+:2]>=DEPTH)bad=1;
   else begin
    if(valid_n[capture_slot[2*c+:2]])bad=1;
    valid_n[capture_slot[2*c+:2]]=1;
   end
  end
 end
 always @(posedge ck or negedge rn)
  if(!rn)begin valid<=0;fault<=0;end
  else begin valid<=valid_n;fault<=fault|bad;end
 genvar g;
 generate for(g=0;g<DEPTH;g=g+1)begin:slot
  reg hit;reg [13:0] row_d;reg [3:0] mask_d;reg [127:0] word_d;reg [7:0] tag_d;
  always @*begin
   hit=0;row_d=0;mask_d=0;word_d=0;tag_d=0;
   for(integer c=0;c<3;c=c+1)if(capture_v[c] && capture_slot[2*c+:2]==g)begin
    hit=1;row_d=row_d|capture_row[14*c+:14];mask_d=mask_d|capture_mask[4*c+:4];
    word_d=word_d|capture_data[128*c+:128];tag_d=tag_d|capture_tag[8*c+:8];
   end
  end
  always @(posedge ck)if(hit)begin
   rows[g]<=row_d;masks[g]<=mask_d;words[g]<=word_d;
`ifdef OT_VM_WSTAGE_MUT_TAG
   tags[g]<=tag_d^8'h1;
`else
   tags[g]<=tag_d;
`endif
  end
 end endgenerate
 initial if(DEPTH<1 ||DEPTH>3)$error("scheduled write storage requires1..3slots");
endmodule

dsfd_vm_static_cap.sv.text:
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------
// dsfd_vm_static_cap (claude S81 VM owner r9, 2026-10-14): the STATIC capture face of the S81 layer-die VM.
// f_capture 13,376 b = dsfd_sp_capture(_c) t_vm (serial 0.9 GHz, no ready): 128 roots x {row1 {data32, addr19}, v1,
// row0 {data32, addr19}, v0} | status 64 ([0] phase live, [2] phase drained, [3] capture fault, [13:4] phase).
//   16 pin-registered hard lanes dsfd_vm_static_cap_leaf over dsfd_vm_static_capl (lane G = roots 8G .. 8G+7, one row write a cycle at
//   most) -> 16 fixed-phase 3:4 transfers ot_s81_vm_x34 (W 542 = {row 14, mask 16, data 512}) -> 16 stream-domain
//   VM write sources (dsfd_vm_static_core sources 32..43, 48..51).
// Rates: 128 elements a stream cycle at full field rate = 8 rows a stream cycle; a lane carries at most one row a
// serial cycle (16 lanes x 3 serial = 48 rows an epoch = 12 a stream cycle of the 16 lanes' sources).  Aligned phases
// (obase multiple of 256 words) put the 16 rows of one key on 16 distinct banks (bank hash row[4:0] ^ {row[7:5],00},
// row[3:0] = G), so the write service's lane rule is met at full rate; any other overlap is a write-service fault.
// Faults (sticky, OR -> fault): lane faults (range, alignment, alias, duplicate, two rows due), capture status fault
// (st[3]), x34 epoch / phase assertions.  No ready, credit, queue or timeout.
// Latency (fixed): element at the f_capture pin, serial edge P -> lane row registered P + 3 (pin, merge, out) -> x34
// stream output at the fixed epoch slot of that serial edge (+2..4 stream edges, x34 header) -> write source.
// ---------------------------------------------------------------------------------------------------------------
module dsfd_vm_static_cap #(parameter integer E = 8) (
    input  wire            ck, rst,             // serial clock, async low reset (released on the common epoch)
    input  wire            cks, rss,            // stream clock / reset
    input  wire [13375:0]  f_capture,
    output wire [15:0]     w_v,                 // stream domain, one row write per lane
    output wire [223:0]    w_row,
    output wire [255:0]    w_m,
    output wire [8191:0]   w_d,
    output wire            fault                // serial-domain sticky level (lanes + status) | stream x34 faults
);
    reg [1:0] rq;
    always @(posedge ck or negedge rst) if (!rst) rq <= 2'b00; else rq <= {rq[0], 1'b1};
    wire rn = rq[1];
    // Status pin register; each hard lane owns its 832-bit data pin register.
    reg [63:0] status_q;
    always @(posedge ck) status_q <= rn ? f_capture[13312 +: 64] : 64'd0;
    wire [63:0] st = status_q;
    reg dr_q, armed, s_flt;
    wire flush = st[2] && !dr_q && armed && !st[0];
    always @(posedge ck)
        if (!rn) begin dr_q <= 1'b0; armed <= 1'b0; s_flt <= 1'b0; end
        else begin
            dr_q <= st[2];
            if (st[3]) s_flt <= 1'b1;
            if (st[0]) armed <= 1'b1;
            if (flush) armed <= 1'b0;
        end
    wire [15:0] lv; wire [16*542-1:0] ld; wire [79:0] lf; wire [15:0] xf;
    genvar g;
    generate for (g = 0; g < 16; g = g + 1) begin : lane
        wire ov; wire [13:0] orow; wire [15:0] om; wire [511:0] od;
        dsfd_vm_static_cap_leaf #(.E(E)) u_l (.ck(ck), .rn(rn), .gid(g[3:0]), .f_c(f_capture[832*g +: 832]), .flush(flush),
            .o_v(ov), .o_row(orow), .o_m(om), .o_d(od), .flt(lf[5*g +: 5]));
        wire xv; wire [541:0] xd;
        ot_s81_vm_x34 #(.W(542)) u_x (.s_ck(ck), .s_rst_n(rst), .s_v(ov), .s_d({od, om, orow}),
            .t_ck(cks), .t_rst_n(rss), .o_v(xv), .o_d(xd), .fault(xf[g]));
        assign w_v[g] = xv;
        assign w_row[14*g +: 14] = xd[13:0];
        assign w_m[16*g +: 16] = xd[29:14];
        assign w_d[512*g +: 512] = xd[541:30];
    end endgenerate
    assign fault = |lf | s_flt | |xf;
endmodule
`default_nettype wire

dsfd_vm_static_cap_leaf.sv.text:
`timescale 1ns/1ps
`default_nettype none
// Physical static capture lane. The input/flush registers formerly in the parent
// live inside this hard boundary. No cycle is added: parent flush is the combinational
// drained-edge predicate which previously fed the parent's flush register.
module dsfd_vm_static_cap_leaf #(parameter integer E=8) (
    input wire ck, rn,
    input wire [3:0] gid,
    input wire [831:0] f_c,
    input wire flush,
    output wire o_v, output wire [13:0] o_row,
    output wire [15:0] o_m, output wire [511:0] o_d,
    output wire [4:0] flt
);
    reg [831:0] pin_c;
    reg [3:0] pin_gid;
    reg pin_flush;
    always @(posedge ck) begin
        pin_c <= rn ? f_c : 832'd0;
        pin_gid <= gid;
        if (!rn) pin_flush <= 1'b0;
        else pin_flush <= flush;
    end
    dsfd_vm_static_capl #(.E(E)) u_l (.ck(ck), .rn(rn), .gid(pin_gid), .f_c(pin_c), .flush(pin_flush),
        .o_v(o_v), .o_row(o_row), .o_m(o_m), .o_d(o_d), .flt(flt));
endmodule
`default_nettype wire

dsfd_vm_static_w0.sv.text:
`timescale 1ns/1ps
`default_nettype none
// Five real W0 leaves replace the scalar 29,203-sink source register.
// All roots reserve the same compiler edge; no data stage or scheduling age is
// added. Each leaf has its own clock pin and local reset release. Epoch outputs
// are observation only: mismatches fault in the control leaf and never gate data.
module dsfd_vm_static_w0_payload #(parameter integer NSRC=53)(
 input wire ck,rst_n,
 input wire [4*NSRC-1:0] i_mask,input wire [128*NSRC-1:0] i_data,
 output reg [4*NSRC-1:0] o_mask,output reg [128*NSRC-1:0] o_data,
 output reg [2:0] o_epoch
);
 reg [1:0] rr;
 always @(posedge ck or negedge rst_n)
  if(!rst_n)rr<=0;else rr<={rr[0],1'b1};
 always @(posedge ck)begin
  o_mask<=i_mask;
`ifdef OT_VM_W0_MUT_SLICE
  o_data<=i_data^{{(128*NSRC-1){1'b0}},1'b1};
`else
  o_data<=i_data;
`endif
  if(!rr[1])o_epoch<=0;else o_epoch<=o_epoch+3'd1;
 end
endmodule
module dsfd_vm_static_w0_header #(parameter integer NSRC=53)(
 input wire ck,rst_n,
 input wire [NSRC-1:0] i_v,input wire [14*NSRC-1:0] i_row,input wire [8*NSRC-1:0] i_tag,
 output reg [NSRC-1:0] o_v,output reg [14*NSRC-1:0] o_row,output reg [8*NSRC-1:0] o_tag,
 output reg [2:0] o_epoch
);
 reg [1:0] rr;
 always @(posedge ck or negedge rst_n)
  if(!rst_n)rr<=0;else rr<={rr[0],1'b1};
 always @(posedge ck)begin
  if(!rr[1])o_v<=0;else o_v<=i_v;
  o_row<=i_row;o_tag<=i_tag;
  if(!rr[1])o_epoch<=0;else o_epoch<=o_epoch+3'd1;
 end
endmodule
`default_nettype wire

dsfd_vm_static512_suhc.sv.text:
`timescale 1ns/1ps
// Four actual128b physical slices, unchanged16384x512 capacity.
// Wires-only parent: each leaf retains its own externally delivered clock.
// Compiler assigns every request and release edge; no ready/credits or waits.
// Per-slice valids and commit observations remain separate: this parent does
// not hide a late physical slice by pretending that a logical row is complete.
module dsfd_vm_static512_suhc(
 input wire [3:0] ck_rscatter,ck_return,input wire [15:0] ck_wscatter,
 input wire [127:0] ck_wcapture,ck_bank,input wire rst_n,
 input wire [47:0] ck_relay_req,ck_relay_rsp,
 input wire [17:0] native_rq_v,input wire [251:0] native_rq_row,input wire [89:0] native_rq_slot,
 input wire [2:0] native_rq_group,input wire [11:0] aux_rq_v,input wire [167:0] aux_rq_row,
 input wire [31:0] wq_v,input wire [447:0] wq_row,input wire [511:0] wq_mask,
 input wire [16383:0] wq_data,input wire [255:0] wq_tag,
 input wire release_v,input wire [2:0] release_group,input wire [31:0] release_mask,
 input wire [17:0] native_expected_v,input wire [89:0] native_release_slot,
 output wire [71:0] native_v,output wire [9215:0] native_data,
 output wire [127:0] group_v,output wire [16383:0] group_data,output wire [11:0] group_id,
 output wire [127:0] commit_v,output wire [1151:0] commit_addr,
 output wire [511:0] commit_mask,output wire [1023:0] commit_tag,
 output wire [15:0] fault
);
 localparam integer NROW=32,SLOT_BITS=5;
 genvar s,q;generate for(s=0;s<4;s=s+1)begin:slice
  wire [4095:0] wd,rd;wire [127:0] wm;wire [31:0] rv;wire [255:0] rt;
  wire [128*NROW-1:0] gd;wire [2303:0] nd;
  for(q=0;q<32;q=q+1)begin:write_rows
   assign wd[128*q+:128]=wq_data[512*q+128*s+:128];
   assign wm[4*q+:4]=wq_mask[16*q+4*s+:4];
  end
  dsfd_vm_static_slice128_suhc u_slice(.ck_rscatter(ck_rscatter[s]),.ck_wcapture(ck_wcapture[32*s+:32]),.ck_wscatter(ck_wscatter[4*s+:4]),
   .ck_bank(ck_bank[32*s+:32]),.rst_n(rst_n),.ck_relay_req(ck_relay_req[12*s+:12]),.ck_relay_rsp(ck_relay_rsp[12*s+:12]),.native_rq_v(native_rq_v),.native_rq_row(native_rq_row),.native_rq_slot(native_rq_slot),
   .native_rq_group(native_rq_group),.aux_rq_v(aux_rq_v),.aux_rq_row(aux_rq_row),
   .wq_v(wq_v),.wq_row(wq_row),.wq_mask(wm),.wq_data(wd),.wq_tag(wq_tag),
   .rs_v(rv),.rs_data(rd),.rs_tag(rt),.commit_v(commit_v[32*s+:32]),
   .commit_addr(commit_addr[288*s+:288]),.commit_mask(commit_mask[128*s+:128]),
   .commit_tag(commit_tag[256*s+:256]),.fault(fault[4*s+:2]));
  dsfd_vm_static_return #(.NROW(NROW)) u_return(.ck(ck_return[s]),.rst_n(rst_n),.i_v(rv),.i_tag(rt),.i_data(rd),
   .release_v(release_v),.release_group(release_group),.release_mask(release_mask),
   .o_v(group_v[NROW*s+:NROW]),.o_data(gd),.o_group(group_id[(8-SLOT_BITS)*s+:8-SLOT_BITS]),.fault(fault[4*s+2]));
  dsfd_vm_static_suhc_return_map u_native(.i_v(group_v[32*s+:32]),.i_data(gd),
   .expected_v(native_expected_v),.release_slot(native_release_slot),
   .o_v(native_v[18*s+:18]),.o_data(nd),.fault(fault[4*s+3]));
  for(q=0;q<18;q=q+1)begin:native_rows
   assign native_data[512*q+128*s+:128]=nd[128*q+:128];
  end
  for(q=0;q<NROW;q=q+1)begin:read_rows
`ifdef OT_VM_512_MUT_SWAP_SLICES
   assign group_data[512*q+128*((s+1)%4)+:128]=gd[128*q+:128];
`else
   assign group_data[512*q+128*s+:128]=gd[128*q+:128];
`endif
  end
 end endgenerate
endmodule

dsfd_vm_static_write_capture128.sv.text:
`timescale 1ns/1ps
// First existing scatter stage, one bank-local 156-bit record. Independent pin/root.
module dsfd_vm_static_write_capture128(
 input wire ck,rst_n,input wire i_v,i_we,input wire [13:0] i_row,
 input wire [3:0] i_mask,input wire [127:0] i_data,input wire [7:0] i_tag,
 output reg o_v,o_we,output reg [13:0] o_row,
 output reg [3:0] o_mask,output reg [127:0] o_data,output reg [7:0] o_tag
);
 reg [1:0] reset_release;
 always @(posedge ck or negedge rst_n)
  if(!rst_n)reset_release<=0;else reset_release<={reset_release[0],1'b1};
 wire rn=reset_release[1];
 always @(posedge ck or negedge rn)if(!rn)o_v<=0;else o_v<=i_v;
 always @(posedge ck)begin o_we<=i_we;o_row<=i_row;o_mask<=i_mask;o_data<=i_data;o_tag<=i_tag;end
endmodule

dsfd_vm_static_xio.sv.text:
`timescale 1ns/1ps
`default_nettype none
// Static VM edge services. Q/G STREAM commands retain the fixed x43 row schedule.
// Collective ABI: four compiler-addressed {tag8,data512,mask16,row14,valid} writes,
// and f_crq={row14,valid} / t_crs={data512,valid} reads. Collective pins connect
// directly to the core auxiliary request/return ports: the core's L12 pin latency
// is unchanged. No legacy CPUSH/CCFG records, queue credits, or runtime pacing.
// Codes 5/7 and LARM group7 are unsupported legacy operations and raise fault.
// Q/G STREAM: code4, dest cd[27:26] (0=query,1=gather), base cd[25:12],
// count-minus-one cd[11:7]. Each unit reserves row[1:0] of aux4..7; a simultaneous
// collective request on the same lane is a compiler schedule fault.
// Q/G return timing retains the existing RLAT13 issue metadata pipeline.
// Collective write tags pass unchanged to the core write/commit pipeline.
module dsfd_vm_static_xio #(parameter integer RLAT = 13) (
    input  wire          cks, rss,              // stream
    input  wire          ck, rst,               // serial (x43 outputs, qSWs)
    // engine 12 native forward
    input  wire          n_v, input wire [83:0] n_d,
    // aux ports 4..7 to / from dsfd_vm_static_core
    output reg  [3:0]    a_v, output reg [55:0] a_row,
    input  wire [3:0]    e_v, input wire [2047:0] e_d,
    // collective
    input  wire [2203:0] f_collective,
    input  wire [14:0]   f_crq,
    output wire [512:0]  t_crs,
    output reg  [3:0]    w_v, output reg [55:0] w_row, output reg [2047:0] w_d, output reg [63:0] w_m, output reg [31:0] w_t,
    // gather
    output wire [511:0]  t_gather,             // serial
    input  wire [10:0]   f_xgo,                // stream
    // scan query
    output wire [512:0]  qSW,                  // serial
    input  wire [2:0]    qSWs,                 // serial
    output wire          fault
);
    reg [1:0] rq;
    always @(posedge cks or negedge rss) if (!rss) rq <= 2'b00; else rq <= {rq[0], 1'b1};
    wire rn = rq[1];
    // epoch sample index of the current edge (same convention as ot_s81_vm_x43: first edge after release = 0)
    reg [1:0] tp;
    always @(posedge cks or negedge rss) if (!rss) tp <= 2'd3; else tp <= tp + 2'd1;
    wire [1:0] tn = tp + 2'd1;
    reg [2:0] f_iss; reg f3, f9, f10; reg [1:0] f_s;
    wire [7:0] flt = {f_s, f10, f9, f3, f_iss};

    // ---------------------------------------------------------------- command decode
    wire [2:0] code = n_d[30:28];
    wire is_st = n_v && code == 3'd4, is_cp = n_v && code == 3'd5, is_cf = n_v && code == 3'd7;
    wire is_cl = n_v && code == 3'd6 && n_d[27:24] == 4'd7;
    // Unit 0 names the direct collective lane; state is used only for Q/G (1/2).
    reg [2:0] act; reg [13:0] u_row [0:2]; reg [4:0] u_n [0:2];
    reg [3:0] stream_av; reg [55:0] stream_ar;
    // ---------------------------------------------------------------- issue (edge I)
    reg [2:0] go; reg [1:0] gl [0:2];
    always @* begin : p_go integer u;
        for (u = 0; u < 3; u = u + 1) begin
            go[u] = (u == 0) ? f_crq[0] : (act[u] && tn != 2'd2);
            gl[u] = (u == 0) ? f_crq[2:1] : u_row[u][1:0];
        end
    end
    reg lane_bad;
    reg [2:0] go_ok;
    always @* begin
        lane_bad = 1'b0; go_ok = go;
        if (go[2] && go_ok[1] && gl[2] == gl[1]) begin lane_bad = 1'b1; go_ok[2] = 1'b0; end
    end
    // The direct collective lane is merged with the registered Q/G requests.
    // A collision faults and collective retains its reserved lane; nothing waits.
    always @* begin
        a_v = stream_av; a_row = stream_ar;
        if (f_crq[0]) begin
            a_v[f_crq[2:1]] = 1'b1;
            a_row[14*f_crq[2:1] +: 14] = f_crq[14:1];
        end
    end
    reg [RLAT-1:0] dC; reg [1:0] dlC [0:RLAT-1];
    reg [RLAT:0] dQ, dG; reg [1:0] dlQ [0:RLAT]; reg [1:0] dlG [0:RLAT];
    always @(posedge cks) begin : p_iss integer u, k; reg [3:0] av;
        if (!rn) begin
            act <= 3'd0; stream_av <= 4'd0; dC <= '0; dQ <= '0; dG <= '0;
            f_iss <= 3'd0;
        end else begin
            av = 4'd0;
            for (u = 1; u < 3; u = u + 1) if (go_ok[u]) av[gl[u]] = 1'b1;
            stream_av <= av;
            for (u = 1; u < 3; u = u + 1) if (go[u]) begin
                u_row[u] <= u_row[u] + 14'd1;
                if (u_n[u] == 5'd0) act[u] <= 1'b0; else u_n[u] <= u_n[u] - 5'd1;
            end
            if (lane_bad) f_iss[1] <= 1'b1;
            dC <= {dC[RLAT-2:0], f_crq[0]};
            dQ <= {dQ[RLAT-1:0], go_ok[1]}; dG <= {dG[RLAT-1:0], go_ok[2]};
            if (f_crq[0] && stream_av[f_crq[2:1]]) f_iss[1] <= 1'b1;
            if (is_cp || is_cf || is_cl) f_iss[2] <= 1'b1;
            if (is_st) begin
                if (n_d[27]) f_iss[2] <= 1'b1;
                else begin
                    if (act[1 + n_d[26]] && !(go[1 + n_d[26]] && u_n[1 + n_d[26]] == 5'd0)) f_iss[0] <= 1'b1;
                    act[1 + n_d[26]] <= 1'b1; u_row[1 + n_d[26]] <= n_d[25:12]; u_n[1 + n_d[26]] <= n_d[11:7];
                end
            end

        end
        for (k = 0; k < 4; k = k + 1)
            stream_ar[14*k +: 14] <= (go_ok[1] && gl[1] == k[1:0]) ? u_row[1] : u_row[2];
        dlC[0] <= f_crq[2:1]; dlQ[0] <= gl[1]; dlG[0] <= gl[2];
        for (k = 1; k <= RLAT; k = k + 1) begin
            dlQ[k] <= dlQ[k-1]; dlG[k] <= dlG[k-1];
        end
        for (k = 1; k < RLAT; k = k + 1) dlC[k] <= dlC[k-1];
    end
    // ---------------------------------------------------------------- return register (edge I + 14)
    wire rC = dC[RLAT-1], rQ = dQ[RLAT], rG = dG[RLAT];
    wire [1:0] lC = dlC[RLAT-1], lQ = dlQ[RLAT], lG = dlG[RLAT];
    wire [3:0] e_exp = (rC ? (4'd1 << lC) : 4'd0) | (rQ ? (4'd1 << lQ) : 4'd0) | (rG ? (4'd1 << lG) : 4'd0);
    wire [511:0] dCw = e_d[512*lC +: 512], dQw = e_d[512*lQ +: 512], dGw = e_d[512*lG +: 512];
    reg q_v; reg [511:0] q_d; reg g_v; reg [510:0] g_d;
    assign t_crs = {dCw, rC};
    reg [2:0] gn; reg [9:0] gph [0:3]; reg [1:0] gw, gr;
    reg [10:0] xq; always @(posedge cks) xq <= rn ? f_xgo : 11'd0;
    always @(posedge cks) begin : p_ret reg push, pop;
        if (!rn) begin
            q_v <= 1'b0; g_v <= 1'b0; gn <= 3'd0; gw <= 2'd0; gr <= 2'd0;
            f3 <= 1'b0; f9 <= 1'b0; f10 <= 1'b0;
        end else begin
            if (e_v != e_exp) f3 <= 1'b1;
            q_v <= rQ; q_d <= dQw;
            g_v <= rG; g_d <= dGw[510:0];
            // gather phase mirror (assertion only)
            push = rG && dGw[1:0] == 2'd0; pop = xq[10];
            if (push) begin gph[gw] <= dGw[58:49]; gw <= gw + 2'd1; end
            if (pop) begin
                if (gn == 3'd0 && !push) f9 <= 1'b1;
                else if (gph[gr] != xq[9:0]) f9 <= 1'b1;
                gr <= gr + 2'd1;
            end
            gn <= gn + (push ? 3'd1 : 3'd0) - ((pop && (gn != 3'd0 || push)) ? 3'd1 : 3'd0);
            if (push && !pop && gn == 3'd4) f10 <= 1'b1;
        end
    end
    // Compiler rows and masks are passed to the core without a landing pointer
    // or extra pin stage. Each lane's 8-bit tag remains part of f_collective ABI;
    // the wrapper/core associates these writes with fixed sources 44..47.
    always @* begin : p_land integer k;
        w_v = 4'd0; w_row = 56'd0; w_d = 2048'd0; w_m = 64'd0; w_t = 32'd0;
        for (k = 0; k < 4; k = k + 1) begin
            w_v[k] = f_collective[551*k];
            w_row[14*k +: 14] = f_collective[551*k+1 +: 14];
            w_m[16*k +: 16] = f_collective[551*k+15 +: 16];
            w_d[512*k +: 512] = f_collective[551*k+31 +: 512];
            `ifdef OT_VM_XIO_MUT_TAG
            w_t[8*k +: 8] = f_collective[551*k+543 +: 8] ^ 8'd1;
`else
            w_t[8*k +: 8] = f_collective[551*k+543 +: 8];
`endif
        end
    end
    // ---------------------------------------------------------------- serial-bound streams
    wire qo_v, go_v; wire [511:0] qo_d; wire [510:0] go_d; wire qf, gf;
    ot_s81_vm_x43 #(.W(512)) u_xq (.t_ck(cks), .t_rst_n(rss), .s_v(q_v), .s_d(q_d), .s_ck(ck), .s_rst_n(rst),
        .o_v(qo_v), .o_d(qo_d), .fault(qf));
    ot_s81_vm_x43 #(.W(511)) u_xg (.t_ck(cks), .t_rst_n(rss), .s_v(g_v), .s_d(g_d), .s_ck(ck), .s_rst_n(rst),
        .o_v(go_v), .o_d(go_d), .fault(gf));
    assign qSW = {qo_d, qo_v};
    assign t_gather = {go_d, go_v};
    reg [1:0] sq; always @(posedge ck or negedge rst) if (!rst) sq <= 2'b00; else sq <= {sq[0], 1'b1};
    reg [2:0] qs_q; reg qs_bad;
    always @(posedge ck) begin
        qs_q <= qSWs;
        if (!sq[1]) qs_bad <= 1'b0; else if (qo_v && !(qs_q[0] && qs_q[1])) qs_bad <= 1'b1;
    end
    always @(posedge cks) if (!rn) f_s <= 2'd0; else begin if (qs_bad) f_s[0] <= 1'b1; if (qf | gf) f_s[1] <= 1'b1; end
    assign fault = |flt;
endmodule
`default_nettype wire

dsfd_vm_static_wdispatch128.sv.text:
`timescale 1ns/1ps
// Actual fixed capture transport. Source ports and per-source capture lane /
// storage slot come from the compiler. Up to3 records per destination bank.
// No arbitration: duplicate destination+capture-lane is a schedule fault.
// Source sampledE0 ->registered outputE1 ->receiving write storage sampleE2.
// One8bank quarter leaf has~11400clock sinks for48source records, below15k.
module dsfd_vm_static_wdispatch128 #(
 parameter integer NSRC=48,parameter integer NBANK=8,parameter integer BANK_BASE=0)(
 input wire ck,rst_n,
 input wire [NSRC-1:0] i_v,input wire [14*NSRC-1:0] i_row,
 input wire [4*NSRC-1:0] i_mask,input wire [128*NSRC-1:0] i_data,
 input wire [8*NSRC-1:0] i_tag,input wire [2*NSRC-1:0] i_capture_lane,i_storage_slot,
 output reg [3*NBANK-1:0] o_v,output reg [6*NBANK-1:0] o_slot,
 output reg [42*NBANK-1:0] o_row,output reg [12*NBANK-1:0] o_mask,
 output reg [384*NBANK-1:0] o_data,output reg [24*NBANK-1:0] o_tag,
 output reg fault
);
 reg [1:0] reset_release;
 always @(posedge ck or negedge rst_n)
  if(!rst_n)reset_release<=0;else reset_release<={reset_release[0],1'b1};
 wire rn=reset_release[1];
 reg [NSRC-1:0] qv;reg [14*NSRC-1:0] qr;reg [4*NSRC-1:0] qm;
 reg [128*NSRC-1:0] qd;reg [8*NSRC-1:0] qt;reg [2*NSRC-1:0] ql,qs;
 always @(posedge ck or negedge rn)if(!rn)qv<=0;else qv<=i_v;
 always @(posedge ck)begin qr<=i_row;qm<=i_mask;qd<=i_data;qt<=i_tag;ql<=i_capture_lane;qs<=i_storage_slot;end
 wire [3*NBANK-1:0] hit,dup;
 genvar g;generate for(g=0;g<3*NBANK;g=g+1)begin:record
  reg h,d;reg [13:0] r;reg [3:0] m;reg [127:0] w;reg [7:0] t;reg [1:0] s;
  reg [4:0] b;integer c;
  always @*begin
   h=0;d=0;r=0;m=0;w=0;t=0;s=0;b=0;
   for(c=0;c<NSRC;c=c+1)begin
    b=qr[14*c+:5]^{qr[14*c+5+:3],2'b00};
    if(qv[c] && b==BANK_BASE+g/3 && ql[2*c+:2]==g%3)begin
     if(h)d=1;h=1;r=r|qr[14*c+:14];m=m|qm[4*c+:4];
     w=w|qd[128*c+:128];t=t|qt[8*c+:8];s=s|qs[2*c+:2];
    end
   end
  end
  assign hit[g]=h;assign dup[g]=d;
  always @(posedge ck)begin
   o_row[14*g+:14]<=r;o_mask[4*g+:4]<=m;o_data[128*g+:128]<=w;o_tag[8*g+:8]<=t;
`ifdef OT_VM_WDISPATCH_MUT_SLOT
   o_slot[2*g+:2]<=s^2'd1;
`else
   o_slot[2*g+:2]<=s;
`endif
  end
 end endgenerate
 reg bad;reg [4:0] bank;integer c;
 always @*begin
  bad=|dup;bank=0;
  for(c=0;c<NSRC;c=c+1)begin
   bank=qr[14*c+:5]^{qr[14*c+5+:3],2'b00};
   if(qv[c] && bank>=BANK_BASE && bank<BANK_BASE+NBANK && ql[2*c+:2]>=3)bad=1;
  end
 end
 always @(posedge ck or negedge rn)
  if(!rn)begin o_v<=0;fault<=0;end else begin o_v<=hit;fault<=fault|bad;end
endmodule

ot_s81_vm_x43.sv.text:
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------
// ot_s81_vm_x43 (claude S81 VM owner r9, 2026-10-14): FIXED-PHASE stream (1.2 GHz) -> serial (0.9 GHz) word transfer
// on the common 3:4 epoch (4 stream = 3 serial cycles = 3.333 ns, both clocks from one source).  The mirror of
// ot_s81_vm_x34 (owner static rule 2026-10-14T18:59: no handshake, FIFO pointers, credit or ready).
// SAMPLE INDEX n = index (0..3) of the stream edge at which this block samples s_v / s_d (edge 0 of an epoch coincides
// with serial edge 0).  Words are accepted at n = 0, 2, 3; a valid word at n = 1 is a SCHEDULE FAULT (never delayed:
// the compiler places serial-bound words off sample index 1; the VM services that feed this block only ever produce
// words on n = 0 / 2 / 3, see dsfd_vm_static_core / _wfc).  Each accepted word is written into its own bank and read by
// the serial side at a FIXED serial edge:
//     n = 2 of epoch E  ->  serial edge 0 of epoch E+1     (launch 1.667 ns, capture 3.333 ns: 1.667 ns)
//     n = 3 of epoch E  ->  serial edge 1 of epoch E+1     (2.500 -> 4.444: 1.944 ns)
//     n = 0 of epoch E  ->  serial edge 2 of epoch E       (0.000 -> 2.222: 2.222 ns)
// Every bank is written once an epoch and read before its next write: full related-clock arcs (STA owns them with
// the epoch multicycle, as x34).  Output o_v / o_d is registered at that serial edge.
// STARTUP CONTRACT (as x34): both resets released so that the first rising edges after release are epoch edge 0 of
// both clocks.  ALIGNMENT ASSERTIONS: every bank carries the stream epoch parity, checked against the serial epoch
// parity on every read after one warm-up epoch; a stream phase marker (high in stream cycle 1 = [0.833, 1.667) ns)
// must be sampled high by serial edge 1 only.  Any slip -> sticky fault (never a re-timed transfer).
// Mutant OT_VM_X43_MUT_PHASE: the n = 3 bank is read one serial edge early (serial edge 0, with the n = 2 bank's slot).
// ---------------------------------------------------------------------------------------------------------------
module ot_s81_vm_x43 #(parameter integer W = 512) (
    input  wire         t_ck, t_rst_n,
    input  wire         s_v, input wire [W-1:0] s_d,
    input  wire         s_ck, s_rst_n,
    output reg          o_v, output reg [W-1:0] o_d,
    output reg          fault
);
    // ---- stream side: tp = index of the last stream edge (3 at reset: the next edge is epoch edge 0)
    reg [1:0] tp; reg te;                       // te = parity of the epoch whose edge 0 was the latest
    reg [W:0] b0, b2, b3; reg [2:0] bpar; reg t_mark; reg ph1_bad;
    wire [1:0] tn = tp + 2'd1;                  // sample index of THIS edge
    always @(posedge t_ck or negedge t_rst_n)
        if (!t_rst_n) begin tp <= 2'd3; te <= 1'b0; bpar <= 3'b000; t_mark <= 1'b0; ph1_bad <= 1'b0; end
        else begin
            tp <= tn;
            t_mark <= tn == 2'd1;               // high from stream edge 1 to stream edge 2
            case (tn)
                2'd0: begin te <= ~te; bpar[0] <= ~te; end
                2'd2: bpar[1] <= te;
                2'd3: bpar[2] <= te;
                default: if (s_v) ph1_bad <= 1'b1;
            endcase
        end
    always @(posedge t_ck)
        case (tn)
            2'd0: b0 <= {s_v, s_d};
            2'd2: b2 <= {s_v, s_d};
            2'd3: b3 <= {s_v, s_d};
            default: ;
        endcase
    // ---- serial side: sp = phase index of the last serial edge (2 at reset: the next edge is epoch edge 0)
    reg [1:0] sp; reg se; reg warm; reg mk;
    wire [1:0] sn = (sp == 2'd2) ? 2'd0 : sp + 2'd1;   // serial edge index of THIS edge
    always @(posedge s_ck or negedge s_rst_n)
        if (!s_rst_n) begin sp <= 2'd2; se <= 1'b0; warm <= 1'b0; o_v <= 1'b0; fault <= 1'b0; mk <= 1'b0; end
        else begin
            sp <= sn;
            mk <= t_mark;
            // PHASE ASSERTION: t_mark sampled at serial edge 1 (1.111 ns) is high; at edges 0 / 2 low.  mk holds the
            // previous edge's sample: after serial edge 1 (sn == 2 now) mk must be 1, else 0.
            if (warm && mk != (sn == 2'd2)) fault <= 1'b1;
            if (ph1_bad) fault <= 1'b1;
            case (sn)
`ifdef OT_VM_X43_MUT_PHASE
                2'd0: begin se <= ~se; o_v <= b3[W]; if (warm && bpar[2] != se) fault <= 1'b1; end
                2'd1: begin warm <= 1'b1; o_v <= b2[W]; end
`else
                2'd0: begin se <= ~se; o_v <= b2[W]; if (warm && bpar[1] != se) fault <= 1'b1; end
                2'd1: begin warm <= 1'b1; o_v <= b3[W]; if (warm && bpar[2] != ~se) fault <= 1'b1; end
`endif
                default: begin o_v <= b0[W]; if (warm && bpar[0] != se) fault <= 1'b1; end
            endcase
        end
    always @(posedge s_ck)
        case (sn)
`ifdef OT_VM_X43_MUT_PHASE
            2'd0: o_d <= b3[W-1:0];
            2'd1: o_d <= b2[W-1:0];
`else
            2'd0: o_d <= b2[W-1:0];
            2'd1: o_d <= b3[W-1:0];
`endif
            default: o_d <= b0[W-1:0];
        endcase
endmodule
`default_nettype wire

dsfd_vm_seq_static.sv.text:
`timescale 1ns/1ps
`default_nettype none
// ---------------------------------------------------------------------------------------------------------------
// dsfd_vm_seq_static (claude S81 VM owner r7, 2026-10-14): the S81 VM SEQUENCER ENGINE, engine 12 of the fixed-cycle
// issuer dsfd_stage_seq_static_c (rtl/dsrom_sys/s81_static_control).  Successor of the diagnostic credit prototype
// dsfd_vm_seq (pulse credits / slot pool / stalls: VOID under the owner rule 2026-10-14T18:59 "static cycle schedule,
// no credits / backpressure").
//
// STATIC CONTRACT.  The compiler assigns every command cycle and every counter slot.  Nothing here waits, stalls,
// queues, arbitrates or returns a credit: every command is taken the cycle it reaches the pin, and its done leaves
// c_done exactly DLAT = 6 stream cycles after the command pin cycle (the issuer's calendar row carries done = issue +
// DLAT + its own pin stages).  Completion of operand rows is NOT a scheduling event: it is VERIFIED at a compiled
// CHECK cycle against the actual write-commit observations of the native static VM (dsfd_vm_static512_rel2
// commit_v / commit_addr / commit_mask, 4 slices x 32 banks), and any discrepancy is a sticky fault (c_st[0]); the
// calendar continues and the job result is discarded outside this block (issuer rule).
//
// Command (issuer native ABI) c_cmd = {v, ctx 1, user 10, pos 21, tok 21, arg 24, row 7}; done tag = {ctx, row}.
//   COMPACT v2 sparse SU operands: codes5/7 select slots0..3/4..7;
//   arg[20:19] slotlow2, [18:9] base/16, [8:7] color, [6:0] nrows-1.
//   Rows are 16*base16+color+4*k, k=0..nrows-1; count exactly16*nrows.
//   Same code/slot with arg[18:0]=19'h7ffff is SPARSECHECK.
//   Sparse ops are consumed here, never forwarded. Dense codes0..3 unchanged.
//   arg[23:21] = code.  Codes 0..3 address COUNTER SLOT s = code (NSLOT 4, compiler-allocated, lifetime checked):
//     ARM   s  {[20] client (0 SU, 1 HC), [19:10] base row / 16, [9:0] nrows - 1}     (same 21-bit compact form as
//           tools/s81_ctrl/vm_arms.py compact_arg; that compiler's single-slot output = code 0)
//           counts every element committed in rows [base, base + nrows) at commit-pin cycles >= ARM pin + 1;
//           expected nelems = 16 * nrows (full-row operand contract).
//     CHECK s  {[20] client, [19:10] = 10'h3FF, [9:0] = 10'h3FF} (that range is impossible for an ARM: base 16368 +
//           1024 rows > 16384).  Verifies, for commits observed at pin cycles <= CHECK pin, count == nelems of slot s
//           and client == the armed client.  Pass: slot s becomes VERIFIED (t_inp of its client, an assertion feed for
//           the consumer's own fixed-start check; it never starts or delays anything).
//   Codes 4/6: NATIVE VM ops (P2ID / P2RD / LARM / XMAP-XGO of dsfd_sp_vm_m) forwarded unchanged on v_cv / v_cd at a
//           fixed stage (pin + 2); the sequencer done is the fixed DLAT done.  The legacy VM channel's own dones only
//           retire the outstanding count (<= VQD, assertion; unknown tag = fault).
// GIVE (vm_arms base16 = count = 1023 on code 0) is a CHECK in this ABI: a static program has no GIVE (a job without
// a VM-produced operand simply has no ARM / CHECK).
//
// Faults (sticky; flt[] for the bench / status, OR on c_st[0]):
//   0 CHECK count != nelems        1 count exceeded nelems (stray / duplicate commit in an armed range)
//   2 CHECK of a slot not armed    3 CHECK client != armed client
//   4 ARM of a slot armed and not yet CHECKed (lifetime)               5 ARM range overlaps another armed slot
//   6 ARM range outside 16384 rows                                   7 EARLY READ: a read request (o_rv / o_rr) at a
//     pin cycle <= the CHECK pin into an armed, not yet verified range  8 legacy channel: unknown / surplus done
//   9 legacy channel: more than VQD native ops outstanding            10 legacy VM fault (v_flt)
//
// Pipeline (stream clock ck; ideal-coincident with the native VM bank clocks, as dsfd_vm_static512_rel2's benches):
//   P0 pin registers: command, 128 commit observations, 32 read requests
//   P1 decode; slot state (base / end / client / open) written for ARM / CHECK of pin t at the end of cycle t+1;
//      per port x slot range compare + masked popcount; read early-check
//   P2 per slot x slice partial sums (32 ports)        P3 per slot total -> count (count of pin-t commits from t+4)
//   P4 CHECK compare (count includes every commit pinned <= CHECK pin)   P5 output retime, P6 done register (c_done at pin + DLAT)
//
// Mutants (negative controls, tb_dsfd_vm_seq_static):
//   OT_VMSS_MUT_SLICE   slice 3 commits are not counted (a late / dropped physical slice hidden): must FAIL
//   OT_VMSS_MUT_RANGE   the armed range includes row base + nrows (off-by-one end): must FAIL
//   OT_VMSS_MUT_DLAT    the done leaves one cycle early (DLAT 5): must FAIL
//   OT_VMSS_MUT_HASH    the logical row ignores the bank hash (bank = row[4:0]): must FAIL
// ---------------------------------------------------------------------------------------------------------------
module dsfd_vm_seq_static #(
    parameter integer NSLOT = 8,
    parameter integer VQD = 8
) (
    input  wire [0:0]    ck,
    input  wire [0:0]    rst,            // async die reset, active low (released synchronously, 2 flops)
    input  wire [84:0]   c_cmd,
    output reg  [8:0]    c_done,
    output reg  [1:0]    c_st,
    // native static VM commit observations (dsfd_vm_static512_rel2: slice s bank b at index 32 s + b)
    input  wire [127:0]  o_cv,
    input  wire [1151:0] o_ca,           // 9-bit bank-local address per bank
    input  wire [511:0]  o_cm,           // 4-word mask per bank (slice s = words 4 s .. 4 s + 3)
    // native static VM logical read requests (dsfd_vm_static512_rel2 rq_v / rq_row)
    input  wire [31:0]   o_rv,
    input  wire [447:0]  o_rr,
    // legacy VM engine channel (dsfd_sp_vm_m cv / cd / dv / dt) for the native codes 4..7
    output reg           v_cv,
    output reg  [83:0]   v_cd,
    input  wire          v_dv,
    input  wire [7:0]    v_dt,
    input  wire          v_flt,
    // VERIFIED levels (assertion feeds for the consumers' fixed-start checks)
    output reg           t_inp_su,
    output reg           t_inp_hc
);
    localparam integer DLAT = 6;
    wire clk = ck[0];
    reg [1:0] rq;
    always @(posedge clk or negedge rst[0]) if (!rst[0]) rq <= 2'b00; else rq <= {rq[0], 1'b1};
    wire rn = rq[1];

    // ------------------------------------------------------------------ P0 pin registers
    reg p0_v; reg [83:0] p0_d;
    reg [127:0] q_cv; reg [1151:0] q_ca; reg [511:0] q_cm;
    reg [31:0] q_rv; reg [447:0] q_rr;
    always @(posedge clk) begin
        if (!rn) begin p0_v <= 1'b0; q_cv <= 128'd0; q_rv <= 32'd0; end
        else begin p0_v <= c_cmd[84]; q_cv <= o_cv; q_rv <= o_rv; end
        p0_d <= c_cmd[83:0]; q_ca <= o_ca; q_cm <= o_cm; q_rr <= o_rr;
    end

    // ------------------------------------------------------------------ P1 decode
    wire [2:0]  d_code = p0_d[30:28];
    wire        d_sparse = d_code == 3'd5 || d_code == 3'd7;
    wire        d_cli = !d_sparse && p0_d[27];
    wire [9:0]  d_b16 = d_sparse ? p0_d[25:16] : p0_d[26:17];
    wire [9:0]  d_nr1 = d_sparse ? {3'd0, p0_d[13:7]} : p0_d[16:7];
    wire [1:0]  d_color = p0_d[15:14];
    wire [2:0]  d_s = d_sparse ? {d_code[1], p0_d[27:26]} : {1'b0, d_code[1:0]};
    wire        d_slot = p0_v && (!d_code[2] || d_sparse);
    wire        d_chk = d_slot && (d_sparse ? p0_d[25:7] == 19'h7ffff : (d_b16 == 10'h3ff && d_nr1 == 10'h3ff));
    wire        d_arm = d_slot && !d_chk;
    wire        d_nat = p0_v && d_code[2] && !d_sparse;
    wire [14:0] d_base = {1'b0, d_b16, 4'd0} + (d_sparse ? {13'd0, d_color} : 15'd0);
`ifdef OT_VMSS_MUT_RANGE
    wire [14:0] d_end = d_base + (d_sparse ? {3'd0, d_nr1, 2'd0} : {5'd0, d_nr1}) + 15'd2;
`else
    wire [14:0] d_end = d_base + (d_sparse ? {3'd0, d_nr1, 2'd0} : {5'd0, d_nr1}) + 15'd1;
`endif
    wire [18:0] d_need = {5'd0, d_nr1, 4'd0} + 19'd16;
    // A sparse operand owns only its color within the bounding interval. Holes
    // never contribute commits, early-read matches, or overlap claims.
    function automatic member(input [13:0] row, input [13:0] lo, input [14:0] hi, input sparse);
        `ifdef OT_VMSS_MUT_DENSECOUNT
        member = row >= lo && {1'b0,row} < hi;
`else
        member = row >= lo && {1'b0,row} < hi && (!sparse || row[1:0] == lo[1:0]);
`endif
    endfunction
    function automatic intersects(input [13:0] al, input [14:0] ah, input asp,
                                  input [13:0] bl, input [14:0] bh, input bsp);
        reg [14:0] first; reg [1:0] color;
        begin
            first = al > bl ? {1'b0,al} : {1'b0,bl};
            color = asp ? al[1:0] : bl[1:0];
            if (asp || bsp) first = first + {13'd0,(color-first[1:0])};
            intersects = !(asp && bsp && al[1:0] != bl[1:0]) && first < ah && first < bh;
        end
    endfunction

    // slot state (pin-t ARM / CHECK visible to compares of pin >= t+1)
    reg [NSLOT-1:0] s_open;               // armed, not yet CHECKed
    reg [NSLOT-1:0] s_sparse;
    reg [NSLOT-1:0] s_cl;                 // client
    reg [NSLOT-1:0] s_ok;                 // verified (CHECK passed), until re-armed
    reg [13:0]      s_lo [0:NSLOT-1];
    reg [14:0]      s_hi [0:NSLOT-1];
    reg [18:0]      s_need [0:NSLOT-1];
    reg [NSLOT-1:0] ovl;
    always @* begin : p_ovl integer k;
        for (k = 0; k < NSLOT; k = k + 1)
            ovl[k] = s_open[k] && k != d_s && intersects(s_lo[k], s_hi[k], s_sparse[k], d_base[13:0], d_end, d_sparse);
    end

    // ------------------------------------------------------------------ P1 per-port compares
    // logical row of slice s bank b: row[13:5] = addr, row[4:0] = b ^ {addr[2:0], 2'b00}
    reg [NSLOT*384-1:0] pc;     // registered per slot x port masked counts (0..4)
    reg [NSLOT-1:0] early;
    always @(posedge clk) begin : p_pc integer s, p; reg [13:0] row; reg [8:0] a;
        for (p = 0; p < 128; p = p + 1) begin
            a = q_ca[9*p +: 9];
`ifdef OT_VMSS_MUT_HASH
            row = {a, p[4:0]};
`else
            row = {a, p[4:0] ^ {a[2:0], 2'b00}};
`endif
            for (s = 0; s < NSLOT; s = s + 1)
                pc[384*s + 3*p +: 3] <= (q_cv[p] && s_open[s] && member(row, s_lo[s], s_hi[s], s_sparse[s]))
                            ? ({2'b0, q_cm[4*p]} + {2'b0, q_cm[4*p+1]} + {2'b0, q_cm[4*p+2]} + {2'b0, q_cm[4*p+3]}) : 3'd0;
        end
    end
    always @* begin : p_early integer s, r;
        early = {NSLOT{1'b0}};
        for (s = 0; s < NSLOT; s = s + 1)
            for (r = 0; r < 32; r = r + 1)
                if (q_rv[r] && s_open[s] && member(q_rr[14*r +: 14], s_lo[s], s_hi[s], s_sparse[s])) early[s] = 1'b1;
    end

    // ------------------------------------------------------------------ P2 per slot x slice partial sums
    reg [NSLOT*32-1:0] ps;
    always @(posedge clk) begin : p_p2 reg [7:0] t; integer s, g, b;
        for (s = 0; s < NSLOT; s = s + 1)
            for (g = 0; g < 4; g = g + 1) begin
                t = 8'd0;
                for (b = 0; b < 32; b = b + 1) t = t + {5'd0, pc[384*s + 3*(32*g + b) +: 3]};
`ifdef OT_VMSS_MUT_SLICE
                if (g == 3) t = 8'd0;                                    // MUTANT: slice 3 never counted
`endif
                ps[32*s + 8*g +: 8] <= t;
            end
    end

    // command pipeline P1 -> P6 (fixed: every command takes the same stages)
    reg        c1_v, c2_v, c3_v, c4_v, c5_v;
    reg        c1_chk, c2_chk, c3_chk;
    reg        c1_arm, c2_arm;
    reg [2:0]  c1_s, c2_s, c3_s;
    reg        c1_cl, c2_cl, c3_cl;
    reg [7:0]  c1_t, c2_t, c3_t, c4_t, c5_t;
    reg [18:0] c1_n, c2_n, c3_n;           // the CHECKed arm's nelems, taken at decode (a re-ARM may follow at once)

    // ------------------------------------------------------------------ P3 count, P4 check
    reg [19:0] cnt [0:NSLOT-1];
    reg [NSLOT-1:0] armq;                 // ARM of slot s reached P2 (clear the count with that cycle's old-range sum)
    reg        pend_chk; reg [2:0] pend_s; reg pend_cl;
    reg [10:0] flt;
    // native outstanding
    reg [$clog2(VQD+1):0] vout;
    reg [1:0] vf_s;
    always @(posedge clk) begin : p_main reg [9:0] tot; integer z;
        vf_s <= {vf_s[0], v_flt};
        if (!rn) begin
            s_open <= 0; s_sparse <= 0; s_cl <= 0; s_ok <= 0; flt <= 11'd0; armq <= 0;
            c1_v <= 1'b0; c2_v <= 1'b0; c3_v <= 1'b0; c4_v <= 1'b0; c5_v <= 1'b0; c1_chk <= 1'b0; c2_chk <= 1'b0; c3_chk <= 1'b0;
            c1_arm <= 1'b0; c2_arm <= 1'b0; v_cv <= 1'b0; vout <= 0; t_inp_su <= 1'b0; t_inp_hc <= 1'b0;
            for (z = 0; z < NSLOT; z = z + 1) begin cnt[z] <= 20'd0; s_lo[z] <= 14'd0; s_hi[z] <= 15'd0; s_need[z] <= 19'd0; end
        end else begin
            // ---- P1: slot state
            if (d_arm) begin
                if (s_open[d_s]) flt[4] <= 1'b1;
                if (|ovl) flt[5] <= 1'b1;
                if (d_end > 15'd16384) flt[6] <= 1'b1;
                s_open[d_s] <= 1'b1; s_ok[d_s] <= 1'b0; s_cl[d_s] <= d_cli;
                s_sparse[d_s] <= d_sparse; s_lo[d_s] <= d_base[13:0]; s_hi[d_s] <= d_end; s_need[d_s] <= d_need;
            end
            if (d_chk) begin
                if (!s_open[d_s]) flt[2] <= 1'b1;
                else if ((s_cl[d_s] != d_cli || s_sparse[d_s] != d_sparse)) flt[3] <= 1'b1;
                s_open[d_s] <= 1'b0;      // reads at pin >= CHECK pin + 1 are legal
            end
            if (|early) flt[7] <= 1'b1;
            c1_n <= s_need[d_s]; c1_v <= p0_v; c1_chk <= d_chk; c1_arm <= d_arm; c1_s <= d_s; c1_cl <= d_cli; c1_t <= {p0_d[83], p0_d[6:0]};
            // ---- native forward (pin + 2)
            v_cv <= d_nat; v_cd <= p0_d;
            if (v_dv && vout == 0) flt[8] <= 1'b1;
            if (vout + (d_nat ? 1 : 0) - ((v_dv && vout != 0) ? 1 : 0) > VQD) flt[9] <= 1'b1;
            vout <= vout + (d_nat ? 1 : 0) - ((v_dv && vout != 0) ? 1 : 0);
            if (vf_s[1]) flt[10] <= 1'b1;
            // ---- P2 stage of the command
            c2_n <= c1_n; c2_v <= c1_v; c2_chk <= c1_chk; c2_arm <= c1_arm; c2_s <= c1_s; c2_cl <= c1_cl; c2_t <= c1_t;
            // ---- P3: accumulate (pin-t commits: pc at t+2, ps at t+3, count at t+4)
            for (z = 0; z < NSLOT; z = z + 1) begin
                tot = {2'b0, ps[32*z +: 8]} + {2'b0, ps[32*z + 8 +: 8]} + {2'b0, ps[32*z + 16 +: 8]} + {2'b0, ps[32*z + 24 +: 8]};
                if (c2_arm && c2_s == z) cnt[z] <= {10'd0, tot};       // first new-range sums (pin ARM+1)
                else cnt[z] <= cnt[z] + {10'd0, tot};
                if (!(c2_arm && c2_s == z) && !(c1_arm && c1_s == z) && cnt[z] > {1'b0, s_need[z]}) flt[1] <= 1'b1;
            end
            c3_n <= c2_n; c3_v <= c2_v; c3_chk <= c2_chk; c3_s <= c2_s; c3_cl <= c2_cl; c3_t <= c2_t;
            // ---- P4: CHECK compare (count now holds commits pinned <= CHECK pin)
            if (c3_chk) begin
                if (cnt[c3_s] != {1'b0, c3_n}) flt[0] <= 1'b1;
                // verified unless the slot was re-armed after this CHECK (ARM pin <= CHECK pin + 3)
                else if (!s_open[c3_s] && !(d_arm && d_s == c3_s)) s_ok[c3_s] <= 1'b1;
            end
            c4_v <= c3_v; c4_t <= c3_t;
            c5_v <= c4_v; c5_t <= c4_t;
            begin : p_inp reg su, hc;
                su = 1'b0; hc = 1'b0;
                for (z = 0; z < NSLOT; z = z + 1) begin
                    if (s_ok[z] && !s_cl[z]) su = 1'b1;
                    if (s_ok[z] &&  s_cl[z]) hc = 1'b1;
                end
                t_inp_su <= su; t_inp_hc <= hc;
            end
        end
    end
    // ------------------------------------------------------------------ P6 done / status (die-face flops)
`ifdef OT_VMSS_MUT_DLAT
    wire       dn_v = c4_v;  wire [7:0] dn_t = c4_t;                     // MUTANT: one stage early
`else
    wire       dn_v = c5_v;  wire [7:0] dn_t = c5_t;
`endif
    always @(posedge clk or negedge rst[0])
        if (!rst[0]) begin c_done <= 9'd0; c_st <= 2'b00; end
        else begin c_done <= (dn_v && rn) ? {1'b1, dn_t} : 9'd0; c_st <= {rn, |flt}; end
endmodule
`default_nettype wire
